INSERT INTO `wp_formmaker_themes` (`id`, `title`, `css`, `default`) VALUES
(1, 'Theme 01 blue', '.wdform-page-and-images .other_input\r\n{\r\nmax-width: none;\r\n}\r\nbutton,\r\ninput,\r\nselect,\r\ntextarea\r\n{\r\nfont-size:14px;\r\n}\r\n.warning,\r\n.error\r\n{\r\nbackground-color: #F0EFEF;\r\nborder: 1px solid #013D7C;\r\nborder-radius: 5px;\r\ncolor: #013D7C;\r\npadding: 5px;\r\n}\r\n.warning *,\r\n.error *\r\n{\r\nmargin:0;\r\n}\r\n.recaptcha_input_area input\r\n{\r\nheight:initial !important;\r\n}\r\ninput[type=\"radio\"]\r\n{\r\nborder:none !important;\r\noutline:none !important;\r\n}\r\ninput[type=\"checkbox\"]\r\n{\r\nborder:none !important;\r\noutline:none !important;\r\n}\r\na.ui-spinner-button\r\n{\r\nborder-radius:0px !important;\r\nbackground: none!important;\r\n}\r\n\r\na.ui-slider-handle {\r\nwidth: 13px;\r\nheight: 13px;\r\ntop: -4px;\r\nborder: 0px;\r\nborder-radius: 13px;\r\nbackground: #FAFAFA;\r\nborder: 3px solid #B1B1B1;\r\noutline: none;\r\n}\r\n\r\n.ui-slider {\r\n	height: 6px;\r\n	background: #F5F5F5 !important;\r\n	margin: 7px 0px;\r\n}\r\n.wdform_grading input {\r\n	width: 100px;\r\n}\r\n.wdform-matrix-cell input[type=\"text\"] {\r\n	width: 100px;\r\nfont-size: 14px !important;\r\n}\r\n.wdform-matrix-cell select {\r\n	width: 60px;\r\nfont-size: 14px !important;\r\n}\r\n.wdform_section .wdform_column:last-child {\r\n	padding-right: 0px !important;\r\n}\r\n.wdform_preload {\r\n	display: none;\r\n}\r\n.wdform_grading {\r\n	padding: 3px 0px;\r\n}\r\n.wdform-matrix-table {\r\n	display: table;\r\n	border-spacing: 0px;\r\n}\r\n.wdform-matrix-column {\r\n	text-align: left;\r\n	display: table-cell;\r\n}\r\n.wdform-matrix-cell {\r\n	text-align: center;\r\n	display: table-cell;\r\n	padding: 6px 10px;\r\n}\r\n.wdform-matrix-head>div {\r\n	display: table-cell;\r\n	text-align: center;\r\n}\r\n.wdform-matrix-head {\r\n	display: table-row;\r\n}\r\n.wdform-matrix-row0 {\r\n	background: #DFDFDF;\r\n	display: table-row;\r\n}\r\n.wdform-matrix-row1 {\r\n	background: #E9E9E9;\r\n	display: table-row;\r\n}\r\n.selected-text {\r\n	text-align: left;\r\n	color: #000;\r\n}\r\n.wdform-quantity {\r\n	width: 30px;\r\n	margin: 2px 0px;\r\n}\r\n.wdform_scale_rating label {\r\n	vertical-align: middle;\r\n}\r\n.ui-corner-all {\r\n	border-radius: 0px;\r\n}\r\n.ui-widget-content {\r\n	border: 0px;\r\n	background: transparent;\r\n}\r\n\r\n\r\n.ui-slider-range {\r\n	background: #8A8A8A !important;\r\n}\r\n.wdform_map {\r\n	border: 6px solid #fff;\r\n}\r\n.wdform-page-and-images {\r\n	width: 100%;\r\n	border: 0px solid #000 !important;\r\npadding-left:10px;\r\n}\r\n.paypal-property {\r\n	display: inline-block;\r\n	margin-right: 15px;\r\n	vertical-align: middle;\r\n}\r\n.sel-wrap {\r\n	display: inline-block;\r\n	vertical-align: middle;\r\n	width:100%;\r\n}\r\n\r\n.sel-imul {\r\n	display: none;\r\n}\r\n.sel-imul .sel-selected {\r\n	cursor: pointer;\r\n	position: relative;\r\n	display: inline-block;\r\n	border-radius: 0px;\r\n	padding: 0px 0px 0px 2px;\r\n	font-size: 13px;\r\n	height: 22px;\r\n	line-height: 22px;\r\n	overflow: hidden;\r\n	background: #F8F8F8;\r\n	border: 0px solid #D3D3D3;\r\n	background-position: right 2px center;\r\n	width: 100%;\r\n}\r\n.sel-imul.act .sel-selected {\r\n	background: #fff;\r\n}\r\n.sel-selected .sel-arraw {\r\n	height: 23px;\r\n	width: 30px;\r\n	background: url([SITE_ROOT]/images/09/01.png) 50% 50% no-repeat;\r\n	position: absolute;\r\n	top: 0px;\r\n	right: 0px;\r\n	padding: 0px;\r\n}\r\n.sel-imul:hover .sel-selected .sel-arraw {\r\n// background-color:#e0e0e0;\r\n// border-left:1px solid #bbb;\r\n}\r\n.sel-imul.act .sel-selected .sel-arraw {\r\n// background-color:#e0e0e0;\r\n// border-left:1px solid #bbb;\r\n}\r\n.sel-imul .sel-options {\r\n	background: #fff;\r\n	border: 1px solid #dbdbdb;\r\n	border-top: none;\r\n	position: absolute;\r\n	width: inherit;\r\n	display: none;\r\n	z-index: 10;\r\n	max-height: 200px;\r\n	overflow-y: auto;\r\n	overflow-x: hidden;\r\n}\r\n.sel-options .sel-option {\r\n	padding: 3px 4px;\r\n	font-size: 13px;\r\n	border: 1px solid #fff;\r\n	border-right: none;\r\n	border-left: none;\r\n	text-align: left;\r\n}\r\n.sel-options .sel-option:hover {\r\n	border-color: #dbdbdb;\r\n	cursor: pointer;\r\n}\r\n.sel-options .sel-option.sel-ed {\r\n	background: #dbdbdb;\r\n	border-color: #dbdbdb;\r\n}\r\ninput[type=text]{\r\n	margin: 0px;\r\n}\r\ninput[type=password]{\r\n	margin: 0px;\r\n}\r\ninput[type=url]{\r\n	margin: 0px;\r\n}\r\ninput[type=email]{\r\n	margin: 0px;\r\n}\r\ninput.text{\r\n	margin: 0px;\r\n}\r\ninput.title{\r\n	margin: 0px;\r\n}\r\ntextarea{\r\n	margin: 0px;\r\n}\r\nselect {\r\n	margin: 0px;\r\n}\r\n.form-error {\r\n	border-color: red !important;\r\n}\r\n.form-error:focus {\r\n	border-color: red !important;\r\n}\r\n.wdform-field {\r\n	display: table-cell;\r\n	padding: 5px 0px;\r\n}\r\n.wdform-label-section{\r\n	text-align: left;\r\n	display: table-cell;\r\n}\r\n.wdform-element-section {\r\n	text-align: left;\r\n	display: table-cell;\r\n	min-width: 140px;\r\n}\r\n.file-upload input {\r\n	position: absolute;\r\n	visibility: hidden;\r\n}\r\n.file-upload-status {\r\n	margin-left: 10px;\r\n	max-width: 200px;\r\n	font-weight: bold;\r\n	font-size: 16px;\r\n	color: #888;\r\n	position: absolute;\r\n	border-radius: 0px;\r\n	height: 23px;\r\n	padding-left: 5px;\r\n	padding-right: 5px;\r\n	white-space: nowrap;\r\n	overflow: hidden;\r\n	}\r\n.file-picker {\r\n	width: 41px;\r\n	height: 32px;\r\n	background: url([SITE_ROOT]/images/10/01/upload.png) no-repeat;\r\n	display: inline-block;\r\n}\r\n.next-page div.wdform-page-button {\r\ncolor: #FFF;\r\ncursor: pointer;\r\ndisplay: inline-block;\r\nheight: 38px;\r\nline-height: 35px;\r\nbackground:url([SITE_ROOT]/images/10/next.png) no-repeat right #013D7C;\r\npadding: 0px 36px 0 20px;\r\nvertical-align: middle;\r\nfont-size: 18px;\r\nborder-top-right-radius: 7px;\r\nborder-bottom-right-radius: 7px;\r\n}\r\n.previous-page div.wdform-page-button {\r\ncolor: #A2A2A2;\r\ncursor: pointer;\r\ndisplay: inline-block;\r\nheight: 37px;\r\nline-height: 35px;\r\nbackground:url([SITE_ROOT]/images/09/previous.png) no-repeat left #F1F1F1;\r\npadding: 0 20px 0 36px;\r\nvertical-align: middle;\r\nfont-size: 18px;\r\nborder-top-left-radius: 7px;\r\nborder-bottom-left-radius: 7px;\r\n}\r\n.button-submit {\r\n	color: #ffffff;\r\n	cursor: pointer;\r\n	display: inline-block;\r\n	line-height: 35px;\r\n	background: #013D7C;\r\n	padding: 0px 20px;\r\n	vertical-align: middle;\r\n	font-size: 18px;\r\n	min-width: 80px;\r\n	min-height: 35px;\r\n	font-family: Segoe UI;\r\n		border: 1px solid transparent;\r\n	margin: 5px;\r\n}\r\n.button-reset {\r\n	color: #787878;\r\n	cursor: pointer;\r\n	display: inline-block;\r\n	line-height: 35px;\r\n	background: #F0EFEF;\r\n	padding: 0px 20px;\r\n	vertical-align: middle;\r\n	font-size: 18px;\r\n	min-width: 80px;\r\n	min-height: 35px;\r\n	font-family: Segoe UI;\r\n	float: right;\r\n	border: 1px solid transparent;\r\n	margin: 5px;\r\n}\r\n.wdform_page {\r\n	background: #FFFFFF;\r\n	padding-top: 15px;\r\n	border-radius: 0px;\r\n	font-family: Segoe UI;\r\n}\r\n.wdform_column {\r\n	border-right: none !important;\r\n	padding-right: 50px !important;\r\n	float: left;\r\n	border-spacing: 2px;\r\n	border-collapse: separate !important;\r\n}\r\n.wdform_section_break2 {\r\n	color: #013D7C;\r\n	display: inline-block;\r\n	text-align: left;\r\n	font-size: 23px;\r\nmargin: 16px 10px 40px 0px;\r\n}\r\n\r\n.wdform_section_break {\r\n	color: #013D7C;\r\n	font-size: 23px;\r\nmargin: 16px 0px;\r\n}\r\n\r\n.wdform_section {\r\n	display: inline-block;\r\n}\r\nselect {\r\n	padding: 2px;\r\n	height: 26px;\r\n	border: 1px solid #B7B7B7;\r\nbackground: #F8F8F8;\r\nfont-size: 14px !important;\r\n}\r\ninput[type=\"text\"]{\r\n	border-radius: 0px;\r\n	height: 22px;\r\n	padding:0 3px !important;\r\n	background: #F8F8F8;\r\nborder:1px solid #B7B7B7;\r\nfont-size: 14px !important;\r\n}\r\ninput[type=\"password\"]{\r\n	border-radius: 0px;\r\n	height: 22px;\r\n	padding:0 3px !important;\r\n	background: #F8F8F8;\r\nborder:1px solid #B7B7B7;\r\nfont-size: 14px !important;\r\n}\r\ntextarea {\r\n	border-radius: 0px;\r\n	height: 22px;\r\n	padding:0 3px !important;\r\n	background: #F8F8F8;\r\nborder:1px solid #B7B7B7;\r\nfont-size: 14px !important;\r\n}\r\ninput[type=\"text\"]:focus{\r\n	outline: none;\r\n}\r\ninput[type=\"password\"]:focus{\r\n	outline: none;\r\n}\r\ntextarea:focus{\r\n	outline: none;\r\n}\r\nselect {\r\n	outline: none;\r\n}\r\n.input_deactive {\r\n	color: #999999;\r\n	font-style: italic;\r\n}\r\n.input_active {\r\n	color: #000000;\r\n	font-style: normal;\r\n}\r\n.am_pm_select {\r\n	width: 30px;\r\n	vertical-align: middle;\r\n}\r\n\r\n\r\n.wdform-calendar-button,\r\n.wdform-calendar-button:hover {\r\n  display:inline-block;\r\n	background: transparent url([SITE_ROOT]/images/03/date.png) no-repeat !important;\r\n	border: 0px;\r\n	color: transparent;\r\n	width: 22px;\r\n	height: 22px;\r\n	position: relative;\r\n	left: -22px;\r\n	vertical-align: top;\r\n	outline: none;\r\n}\r\n\r\n\r\n.forlabs {\r\n	float: right;\r\n	margin-right: 20px;\r\n}\r\n\r\n.if-ie-div-label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=100)\" !important;\r\n	filter: alpha(opacity=100) !important;\r\n	opacity: 1 !important;\r\n}\r\n.wdform-ch-rad-label {\r\n	display: inline;\r\n	margin: -4px 5px 5px 5px;\r\n	float: left;\r\n	color: #000;\r\n	cursor: pointer\r\n}\r\ntextarea {\r\n	padding-top: 5px;\r\n}\r\n.wdform-date {\r\n  display:inline-block;\r\n	width: 105px\r\n}\r\n.wdform_footer {\r\n	margin-top: 15px;\r\n}\r\n.page-numbers {\r\n	vertical-align: middle;\r\n}\r\n.time_box {\r\n	text-align: right;\r\n	width: 30px;\r\n	vertical-align: middle\r\n}\r\n.mini_label {\r\n	font-size: 10px;\r\n	font-family: \"Lucida Grande\", Tahoma, Arial, Verdana, sans-serif;\r\n	color: #8A8A8A;\r\n}\r\n.wdform-label {\r\n	border: none;\r\n	color: #000;\r\n	vertical-align: top;\r\n	line-height: 17px;\r\n}\r\n.wdform_colon {\r\n	color: #000\r\n}\r\n.wdform_separator {\r\n	font-style: bold;\r\n	vertical-align: middle;\r\n	color: #000;\r\n}\r\n.wdform_line {\r\n	color: #000\r\n}\r\n.wdform-required {\r\n	border: none;\r\n	color: red;\r\n	vertical-align: top;\r\n}\r\n.captcha_img {\r\n	border-width: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	cursor: pointer;\r\n	border-radius: 0px;\r\n}\r\n.captcha_refresh {\r\n	width: 30px;\r\n	height: 30px;\r\n	border-width: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	vertical-align: middle;\r\n	cursor: pointer;\r\n	background-image: url([SITE_ROOT]/images/refresh_black.png);\r\n}\r\n.captcha_input {\r\n	height: 20px;\r\n	border-width: 1px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	vertical-align: middle;\r\n}\r\n.file_upload {\r\n	border: 0px solid white;\r\n	border-radius: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	color: black;\r\n	background-color: white;\r\n}\r\n.page_deactive {\r\ncolor: #013E7D;\r\nbackground-color: #FFF;\r\ncursor: pointer;\r\ndisplay: inline-block;\r\nheight: 29px;\r\ntext-align: center;\r\nvertical-align: bottom;\r\npadding: 5px 25px 0px 25px;\r\nfont-size: 16px;\r\nfont-weight:bold;\r\n}\r\n.page_active {\r\ncolor: #FFF;\r\ncursor: pointer;\r\nbackground-color: #013E7D;\r\ndisplay: inline-block;\r\nvertical-align: bottom;\r\nheight: 29px;\r\ntext-align: center;\r\nfont-size: 20px;\r\npadding: 5px 25px 0px 25px;\r\nline-height: 26px;\r\nfont-weight:bold;\r\n}\r\n.page_percentage_active {\r\npadding: 0px;\r\nmargin: 0px;\r\nborder-spacing: 0px;\r\nheight: 16px;\r\nline-height: 16px;\r\nfont-size: 15px;\r\nfloat: left;\r\ntext-align: right !important;\r\nz-index: 1;\r\nposition: relative;\r\nvertical-align: middle;\r\nbackground: #013E7F;\r\ncolor: #fff;\r\nborder-top-left-radius: 5px;\r\nborder-bottom-left-radius: 5px;\r\n}\r\n.page_percentage_deactive {\r\nheight: 16px;\r\nline-height: 16px;\r\nbackground-color: #F1F1F1;\r\ntext-align: left !important;\r\nmargin-bottom: 1px;\r\nborder-radius: 5px;\r\n}\r\n.page_numbers {\r\n	font-size: 14px;\r\n	color: #000;\r\n}\r\n.phone_area_code {\r\n	width: 50px;\r\n}\r\n.phone_number {\r\n	width: 100px;\r\n}\r\nbutton {\r\n	cursor: pointer;\r\n}\r\n.other_input {\r\n	border-radius: 0px;\r\n	border-width: 1px;\r\n	height: 16px;\r\n	font-size: 12px;\r\n	padding: 1px;\r\n	margin: 1px;\r\n	margin-left: 25px;\r\n	z-index: 100;\r\n	position: absolute;\r\n}\r\n.wdform_page_navigation {\r\n	text-align: right !important;\r\n}\r\n\r\n.wdform_percentage_text {\r\nmargin: 3px 5px 3px 9px;\r\ncolor: #FFF;\r\nfont-size: 12px;\r\n}\r\n.wdform_percentage_title {\r\n	color: #6E6E6E;\r\n	font-style: italic;\r\n	margin: 0px 0px 0px 40px;\r\n	display: inline-block;\r\n	line-height: 27px;\r\n	height: 27px;\r\n	vertical-align: middle;\r\n}\r\n.wdform_button button {\r\n	background: #4D792C;\r\n	cursor: pointer;\r\n	font-size: 17px;\r\n	border-radius: 0px;\r\n	min-width: 80px;\r\n	min-height: 31px;\r\n	color: #fff;\r\n	border: 2px solid #68943B;\r\n	margin: 5px;\r\n	box-shadow: 0px 0px 2px #c9c9c9;\r\n	font-family: Segoe UI;\r\n}', 0),
