\n	margin: 1px;\r\n	margin-left: 25px;\r\n	z-index: 100;\r\n	position: absolute;\r\n}\r\n.wdform_page_navigation {\r\n	text-align: center!important;\r\n	margin-bottom: 0px;\r\n}\r\n.wdform_percentage_text {\r\n	margin: 3px -34px 3px 9px;\r\n	color: #FFFFFF;\r\n	font-weight: normal;\r\n	font-size: 12px;\r\nline-height:18px;\r\n}\r\n.wdform_percentage_title {\r\n	color: #000000;\r\n	font-style: italic;\r\n	margin: 0px 0px 0px 40px;\r\n	display: inline-block;\r\n	line-height: 20px;\r\n	height: 20px;\r\n	vertical-align: middle;\r\n}\r\n.wdform_percentage_arrow {\r\n	display: inline-block;\r\n	width: 34px;\r\n	height: 18px;\r\n	background: url([SITE_ROOT]/images/03/02/percentage_arrow.png);\r\n	position: relative;\r\n	left: -1px;\r\ntop:0px;\r\n	z-index: 0;\r\n	vertical-align: middle;\r\n}\r\n.wdform_button button {\r\n	background: #4D792C;\r\n	cursor: pointer;\r\n	font-size: 17px;\r\n	border-radius: 0px;\r\n	min-width: 80px;\r\n	min-height: 31px;\r\n	color: #fff;\r\n	border: 2px solid #68943B;\r\n	margin: 5px;\r\n	box-shadow: 0px 0px 2px #c9c9c9;\r\n	font-family: Segoe UI;\r\n}', 0);
