(11, 'Theme 03 dark cyan', '.wdform-page-and-images .other_input\r\n{\r\nmax-width: none;\r\n}\r\nbutton,\r\ninput,\r\nselect,\r\ntextarea\r\n{\r\nfont-size:14px;\r\n}\r\n.warning,\r\n.error\r\n{\r\nbackground-color: #F0EEEF;\r\nborder: 1px solid #0B7A97;\r\nmargin-bottom: 10px;\r\ncolor: #0B7A97;\r\npadding: 5px;\r\n}\r\n.warning *,\r\n.error *\r\n{\r\nmargin:0;\r\n}\r\n.recaptcha_input_area input\r\n{\r\nheight:initial !important;\r\n}\r\na.ui-slider-handle {\r\n	border-radius: 0px;\r\n	border: 1px solid #39680B;\r\n	background: #C9FD9C;\r\n	height: 13px;\r\n	width: 13px;\r\n}\r\n.ui-slider-horizontal .ui-slider-handle {\r\n	top: -5px !important;\r\n}\r\n.ui-slider {\r\n	height: 6px;\r\n	background: #fff !important;\r\n	margin: 7px 0px;\r\n}\r\n.wdform_grading input {\r\n	width: 100px;\r\n}\r\n.wdform-matrix-cell input[type=\"text\"] {\r\n	width: 100px;\r\n}\r\n.wdform-matrix-cell select {\r\n	width: 60px;\r\n}\r\n.wdform_section .wdform_column:last-child {\r\n	padding-right: 0px !important;\r\n}\r\n.wdform_preload {\r\n	display: none;\r\n}\r\n.wdform_grading {\r\n	padding: 3px 0px;\r\n}\r\n.wdform-matrix-table {\r\n	display: table;\r\n	border-spacing: 0px;\r\n}\r\n.wdform-matrix-column {\r\n	text-align: left;\r\n	display: table-cell;\r\n}\r\n.wdform-matrix-cell {\r\n	text-align: center;\r\n	display: table-cell;\r\n	padding: 6px 10px;\r\n}\r\n.wdform-matrix-head>div {\r\n	display: table-cell;\r\n	text-align: center;\r\n}\r\n.wdform-matrix-head {\r\n	display: table-row;\r\n}\r\n.wdform-matrix-row0 {\r\n	background: #DFDFDF;\r\n	display: table-row;\r\n}\r\n.wdform-matrix-row1 {\r\n	background: #E9E9E9;\r\n	display: table-row;\r\n}\r\n.selected-text {\r\n	text-align: left;\r\n}\r\n.wdform-quantity {\r\n	width: 30px;\r\n	margin: 2px 0px;\r\n}\r\n.wdform_scale_rating label {\r\n	vertical-align: middle;\r\n}\r\n.ui-corner-all {\r\n	border-radius: 0px;\r\n}\r\n.ui-widget-content {\r\n	border: 0px;\r\n	background: transparent;\r\n}\r\na.ui-spinner-button:hover {\r\n	backg