filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.wdform-ch-rad-label:hover + .checkbox-div label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.checkbox-div input[type=checkbox]:checked + label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=100)\";\r\n	filter: alpha(opacity=100);\r\n	opacity: 1;\r\n}\r\n.wdform-calendar-button,\r\n.wdform-calendar-button:hover {\r\n  display:inline-block;\r\n	background: transparent url([SITE_ROOT]/images/03/date.png) no-repeat left 50% !important;\r\n	border: 0px;\r\n	color: transparent;\r\n	width: 22px;\r\n	height: 24px;\r\n	position: relative;\r\n	left: -22px;\r\n	vertical-align: top;\r\n}\r\n.wdform-calendar-button:focus {\r\n outline:none; \r\n}\r\n.radio-div input[type=radio] {\r\n	position : absolute;\r\n	z-index: -1;\r\n}\r\n.forlabs {\r\n	float: right;\r\n	margin-right: 20px;\r\n}\r\n.radio-div {\r\n	width: 13px;\r\n	height: 12px;\r\n	background: transparent;\r\n	border: 1px solid #A7A7A7;\r\n	border-radius: 0px;\r\n	position: relative;\r\n	display: inline-block;\r\n	top: 2px;\r\n}\r\n.radio-div label {\r\n	cursor: pointer;\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=0)\";\r\n	filter: alpha(opacity=0);\r\n	opacity: 0;\r\n	content: \"\";\r\n	position: absolute;\r\n	width: 9px;\r\n	height: 8px;\r\n	background: #A7A7A7;\r\n	border-radius: 0px;\r\n	top: 2px;\r\n	left: 2px;\r\n}\r\n.radio-div label:hover {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.radio-div .wdform-ch-rad-label:hover {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.wdform-ch-rad-label:hover + .radio-div label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter