\n	border: 1px solid #ccc;\r\n	padding-left: 5px;\r\n	padding-right: 5px;\r\n	white-space: nowrap;\r\n	overflow: hidden;\r\n	direction: rtl;\r\n	padding-top: 3px;\r\n	margin-top: 2px;\r\n}\r\n.file-picker {\r\n	width: 41px;\r\n	height: 32px;\r\n	background: url([SITE_ROOT]/images/05/01/upload.png) no-repeat;\r\n	display: inline-block;\r\n}\r\n.next-page div.wdform-page-button {\r\n	color: #ffffff;\r\n	cursor: pointer;\r\n	display: inline-block;\r\n	height: 32px;\r\n	line-height: 28px;\r\n	background: url([SITE_ROOT]/images/05/01/nextbg.png) no-repeat;\r\n	padding: 0px 20px 0 0;\r\n	vertical-align: middle;\r\n	font-size: 18px;\r\n	margin-right: 20px;\r\n	margin-left: 20px;\r\n	width: 90px;\r\n}\r\n.next-page div.wdform-page-button:hover {\r\n	background: url([SITE_ROOT]/images/05/01/nextbg_hover.png) no-repeat;\r\n	width: 113px;\r\n}\r\n.previous-page div.wdform-page-button {\r\n	color: #ffffff;\r\n	cursor: pointer;\r\n	display: inline-block;\r\n	height: 32px;\r\n	line-height: 28px;\r\n	background: url([SITE_ROOT]/images/05/01/previousbg.png) no-repeat;\r\n	padding: 0px 0 0 20px;\r\n	vertical-align: middle;\r\n	font-size: 18px;\r\n	margin-right: 20px;\r\n	margin-left: 20px;\r\n	width: 90px;\r\n}\r\n.previous-page div.wdform-page-button:hover {\r\n	background: url([SITE_ROOT]/images/05/01/previousbg_hover.png) no-repeat;\r\n	width: 113px;\r\n}\r\n.button-submit {\r\n	background: url([SITE_ROOT]/images/05/01/submit.png) no-repeat;\r\n	cursor: pointer;\r\n	font-size: 17px;\r\n	border-radius: 0px;\r\n	min-width: 80px;\r\n	min-height: 32px;\r\n	color: #fff;\r\n	margin: 5px;\r\n	border: 0px;\r\n	font-family: Segoe UI;\r\n	font-weight: 500;\r\n	padding: 0 12px 0 24px;\r\n}\r\n.button-reset {\r\n	background: transparent;\r\n	cursor: pointer;\r\n	font-size: 17px;\r\n	min-width: 80px;\r\n	min-height: 34px;\r\n	color: #787878;\r\n	border: 0px;\r\n	margin: 5px;\r\n	font-family: Segoe UI;\r\n	text-decoration: underline;\r\n}\r\n.wdform_page {\r\n	background: #A0CBDB;\r\n	padding: