\n.wdform-label {\r\n	border: none;\r\n	color: #000;\r\n	vertical-align: top;\r\n	line-height: 17px;\r\n}\r\n.wdform_colon {\r\n	color: #000\r\n}\r\n.wdform_separator {\r\n	font-style: bold;\r\n	vertical-align: middle;\r\n	color: #000;\r\n}\r\n.wdform_line {\r\n	color: #000\r\n}\r\n.wdform-required {\r\n	border: none;\r\n	color: red;\r\n	vertical-align: top;\r\n}\r\n.captcha_img {\r\n	border-width: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	cursor: pointer;\r\n}\r\n.captcha_refresh {\r\n	width: 30px;\r\n	height: 30px;\r\n	border-width: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	vertical-align: middle;\r\n	cursor: pointer;\r\n	background-image: url([SITE_ROOT]/images/refresh_black.png);\r\n}\r\n.captcha_input {\r\n	height: 20px;\r\n	border-width: 1px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	vertical-align: middle;\r\n}\r\n.file_upload {\r\n	border: 0px solid white;\r\n	border-radius: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	color: black;\r\n	background-color: white;\r\n}\r\n.page_deactive {\r\n	font-size: 12px;\r\n color: #ffffff;\r\n	cursor: pointer;\r\n	display: inline-block;\r\n	height: 20px;\r\n	text-align: center;\r\n	vertical-align: bottom;\r\n	padding: 5px 25px 0px 25px;\r\n	font-weight: bold;\r\n	background-color: #018D08;\r\n	margin-left: 1px;\r\n}\r\n.page_active {\r\n	color: #fff;\r\n	cursor: pointer;\r\n	background-color: #00AC0A;\r\n	display: inline-block;\r\n	vertical-align: bottom;\r\n	height: 25px;\r\n	text-align: center;\r\n	font-size: 16px;\r\n	padding: 5px 25px 0px 25px;\r\n	margin-left: 1px;\r\n	line-height: 25px;\r\n}\r\n.page_percentage_active {\r\n	padding: 0px;\r\n	margin: 0px;\r\n	border-spacing: 0px;\r\n	height: 27px;\r\n	line-height: 27px;\r\n	font-size: 15px;\r\n	float: left;\r\n	text-align: right !important;\r\n	z-index: 1;\r\n	position: relative;\r\n	vertical-align: middle;\r\n	background: #018F08 ;\r\n	background: -moz-linear-gradient(left, #018D08 0%, #018F08 39%, #00BE0A 100%);\r\n	background: -webkit-gradient(linear, left top, right top, color-stop(0%, #018D08 ), color-stop(39%, #018F08 ), color-stop(100%, #00BE0A ));\r\n	background: -webkit-linear-gradient(left, #018D08 0%, #018F08 39%, #00BE0A 100%);\r\n	background: -o-linear-gradient(left, #018D08 0%, #018F08 39%, #00BE0A 100%);\r\n	background: -ms-linear-gradient(left, #018D08 0%, #018F08 39%, #00BE0A 100%);\r\nbackground: linear-gradient(to right, #018D08 0%, #018F08 39%, #00BE0A 100%);\r\n	border-top-right-radius: 9px;\r\n	border-bottom-right-radius: 9px;\r\n	box-shadow: 2px 0px 7px #9E9B9B;\r\n}\r\n.page_percentage_deactive {\r\n	height: 27px;\r\n	line-height: 27px;\r\n	background-color: #CEE0D3;\r\n	text-align: left !important;\r\n	margin-bottom: 1px;\r\n}\r\n.page_numbers {\r\n	font-size: 14px;\r\n	color: #000;\r\n}\r\n.phone_area_code {\r\n	width: 50px;\r\n}\r\n.phone_number {\r\n	width: 100px;\r\n}\r\nbutton {\r\n	cursor: pointer;\r\n}\r\n.other_input {\r\n	border-radius: 0px;\r\n	border-width: 1px;\r\n	height: 16px;\r\n	font-size: 12px;\r\n	padding: 1px;\r\n	margin: 1px;\r\n	margin-left: 25px;\r\n	z-index: 100;\r\n	position: absolute;\r\n}\r\n.wdform_page_navigation {\r\n	text-align: right !important;\r\n	margin-bottom: 0px;\r\n}\r\n.wdform_percentage_text {\r\n	margin: 3px 5px 3px 9px;\r\n	color: #ffffff;\r\n	font-weight: bold;\r\n}\r\n.wdform_percentage_title {\r\n	color: #6E6E6E;\r\n	font-style: italic;\r\n	margin: 0px 0px 0px 40px;\r\n	display: inline-block;\r\n	line-height: 27px;\r\n	height: 27px;\r\n	vertical-align: middle;\r\n}\r\n.wdform_button button {\r\n	background: #0E4D92;\r\n	cursor: pointer;\r\n	font-size: 17px;\r\n	border-radius: 4px;\r\n	min-width: 80px;\r\n	min-height: 27px;\r\n	color: #fff;\r\n	border: 2px solid #0E3F77;\r\n	margin: 5px;\r\n	box-shadow: 0px 0px 2px #c9c9c9;\r\n	font-family: Segoe UI;\r\n}\r\n.wdform_button button:active {\r\n	border: 2px solid #0B2D52;\r\n	background: #0E3F77;\r\n}', 0);
INSERT INTO `wp_formmaker_themes` (`id`, `title`, `css`, `default`) VALUES
