ate.png) no-repeat !important;\r\n	border: 0px;\r\n	color: transparent;\r\n	width: 22px;\r\n	height: 22px;\r\n	position: relative;\r\n	left: -22px;\r\n	vertical-align: top;\r\n	outline: none;\r\n}\r\n.radio-div input[type=radio] {\r\n	position : absolute;\r\n	z-index: -1;\r\n}\r\n.forlabs {\r\n	float: right;\r\n	margin-right: 20px;\r\n}\r\n.radio-div {\r\n	width: 13px;\r\n	height: 12px;\r\n	background: transparent;\r\n	border: 1px solid #8B8B8B;\r\n	border-radius: 0px;\r\n	position: relative;\r\n	display: inline-block;\r\n	top: 2px;\r\n}\r\n.radio-div label {\r\n	cursor: pointer;\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=0)\";\r\n	filter: alpha(opacity=0);\r\n	opacity: 0;\r\n	content: \"\";\r\n	position: absolute;\r\n	width: 9px;\r\n	height: 8px;\r\n	background: #8B8B8B;\r\n	border-radius: 0px;\r\n	top: 2px;\r\n	left: 2px;\r\n}\r\n.radio-div label:hover {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.radio-div .wdform-ch-rad-label:hover {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.wdform-ch-rad-label:hover + .radio-div label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.radio-div input[type=radio]:checked + label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=100)\";\r\n	filter: alpha(opacity=100);\r\n	opacity: 1;\r\n}\r\n.if-ie-div-label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=100)\" !important;\r\n	filter: alpha(opacity=100) !important;\r\n	opacity: 1 !important;\r\n}\r\n.wdform-ch-rad-label {\r\n	display: inline;\r\n	margin: -4px 5px 5px 5px;\r\n	float: left;\r\n	color: #000;\r\n	cursor: pointer\r\n}\r\ntextarea {\r\n	padding-top: 5px;\r\n}\r\n.wdform-date {\r\n  display:inline-block;\r\n	width: 105px\r\n}\r\n.wdform_footer {\r\n	margin-top: 15px;\r\n}\r\n.page-numbers {\r\n	vertical-align: middle;\r\n}\r\n.time_box {\r\n	text-align: right;\r\n	width: 30px;\r\n	vertical-align: middle\r\n}\r\n.mini_label {\r\n	font-size: 10px;\r\n	font-family: \"Lucida Grande\", Tahoma, Arial, Verdana, sans-serif;\r\n	color: #000;\r\n}\r\n.wdform-label {\r\n	border: none;\r\n	color: #000;\r\n	vertical-align: top;\r\n	line-height: 17px;\r\n}\r\n.wdform_colon {\r\n	color: #000\r\n}\r\n.wdform_separator {\r\n	font-style: bold;\r\n	vertical-align: middle;\r\n	color: #000;\r\n}\r\n.wdform_line {\r\n	color: #000\r\n}\r\n.wdform-required {\r\n	border: none;\r\n	color: red;\r\n	vertical-align: top;\r\n}\r\n.captcha_img {\r\n	border-width: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	cursor: pointer;\r\n	border-radius: 0px;\r\n}\r\n.captcha_refresh {\r\n	width: 30px;\r\n	height: 30px;\r\n	border-width: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	vertical-align: middle;\r\n	cursor: pointer;\r\n	background-image: url([SITE_ROOT]/images/refresh_black.png);\r\n}\r\n.captcha_input {\r\n	height: 20px;\r\n	border-width: 1px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	vertical-align: middle;\r\n}\r\n.file_upload {\r\n	border: 0px solid white;\r\n	border-radius: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	color: black;\r\n	background-color: white;\r\n}\r\n.page_deactive {\r\ncolor: #808080;\r\nbackground-color: #E5E5E5;\r\ncursor: pointer;\r\ndisplay: inline-block;\r\nheight: 27px;\r\ntext-align: center;\r\nvertical-align: bottom;\r\npadding: 5px 25px 0px 25px;\r\nfont-size: 18px;\r\nmargin-left:3px;\r\nmargin-bottom:2px;\r\n}\r\n.page_active {\r\n	color: #C2C2C2;\r\ncursor: pointer;\r\nbackground-color: #FFFFFF;\r\ndisplay: inline-block;\r\nvertical-align: bottom;\r\nheight: 29px;\r\ntext-align: center;\r\nfont-size: 22px;\r\npadding: 5px 25px 0px 25px;\r\nborder: 1px solid #7F7F7F;\r\nmargin-left:3px;\r\nmargin-bottom: -1px;\r\nborder-bottom: none;\r\nline-height: 26px;\r\n}\r\n.page_percentage_active {\r\npadding: 0px;\r\nborder-spacing: 0px;\r\nheight: 10px;\r\nbackground: #E7C85C;\r\nfloat: left;\r\n}\r\n.page_percentage_deactive {\r\nheight: 10px;\r\nline-height: 20px;\r\nbackground-color: #E5E5E5;\r\ntext-align: left !important;\r\nmargin-bottom: 2px;\r\n}\r\n.page_numbers {\r\n	font-size: 14px;\r\n	color: #000;\r\n}\r\n.phone_area_code {\r\n	width: 50px;\r\n}\r\n.phone_number {\r\n	width: 100px;\r\n}\r\nbutton {\r\n	cursor: pointer;\r\n}\r\n.other_input {\r\n	border-radius: 0px;\r\n	border-width: 1px;\r\n	height: 16px;\r\n	font-size: 12px;\r\n	padding: 1px;\r\n	margin: 1px;\r\n	margin-left: 25px;\r\n	z-index: 100;\r\n	position: absolute;\r\n}\r\n.wdform_page_navigation {\r\n	text-align: right !important;\r\n}\r\n\r\n.wdform_percentage_text {\r\ncolor: #fff;\r\nfont-size: 12px;\r\nposition: relative;\r\nbackground: url([SITE_ROOT]/images/09/02/02.png) no-repeat;\r\nwidth: 36px;\r\ndisplay: inline-block;\r\nheight: 36px;\r\ntop: -37px;\r\nleft: 17px;\r\ntext-align: center;\r\nline-height: 27px;\r\nfloat: right;\r\n}\r\n.wdform_percentage_title {\r\n	color: #000000;\r\n	font-style: italic;\r\n	margin: 0px 0px 0px 40px;\r\n	display: inline-block;\r\n	line-height: 20px;\r\n	height: 20px;\r\n	vertical-align: middle;\r\n}\r\n.wdform_button button {\r\n	background: #4D792C;\r\n	cursor: pointer;\r\n	font-size: 17px;\r\n	border-radius: 0px;\r\n	min-width: 80px;\r\n	min-height: 31px;\r\n	color: #fff;\r\n	border: 2px solid #68943B;\r\n	margin: 5px;\r\n	box-shadow: 0px 0px 2px #c9c9c9;\r\n	font-family: Segoe UI;\r\n}', 0);
INSERT INTO `wp_formmaker_themes` (`id`, `title`, `css`, `default`) VALUES
(35, 'Theme 10 orange', '.wdform-page-and-images .other_input\r\n{\r\nmax-width: none;\r\n}\r\nbutton,\r\ninput,\r\nselect,\r\ntextarea\r\n{\r\nfont-size:14px;\r\n}\r\n.warning,\r\n.error\r\n{\r\nbackground-color: #F7D3BB;\r\nborder: 1px solid #FAAA63;\r\nmargin-bottom: 10px;\r\ncolor: #FAAA63;\r\npadding: 5px;\r\n}\r\n.warning *,\r\n.error *\r\n{\r\nmargin:0;\r\n}\r\n.recaptcha_input_area input\r\n{\r\nheight:initial !important;\r\n}\r\n.wdform_grading input {\r\n	width: 100px;\r\n}\r\n.wdform-matrix-cell input[type=\"text\"] {\r\n	width: 100px;\r\n}\r\n.wdform-matrix-cell select {\r\n	width: 60px;\r\n}\r\n.wdform_section .wdform_column:last-child {\r\n	padding-right: 0px !important;\r\n}\r\n.wdform_preload {\r\n	display: none;\r\n	content: url([SITE_ROOT]/images/01/01/next_hoverbg.png) url([SITE_ROOT]/images/01/01/previous_hover.png) url([SITE_ROOT]/images/01/01/next_hover.png);\r\n}\r\n.wdform_grading {\r\n	padding: 3px 0px;\r\n}\r\n.wdform-matrix-table {\r\n	display: table;\r\n	border-spacing: 0px;\r\n}\r\n.wdform-matrix-column {\r\n	text-align: left;\r\n	display: table-cell;\r\n}\r\n.wdform-matrix-cell {\r\n	text-align: center;\r\n	display: table-cell;\r\n	padding: 6px 10px;\r\n}\r\n.wdform-matrix-head>div {\r\n	display: table-cell;\r\n	text-align: center;\r\n}\r\n.wdform-matrix-head {\r\n	display: table-row;\r\n}\r\n.wdform-matrix-row0 {\r\n	background: #DFDFDF;\r\n	display: table-row;\r\n}\r\n.wdform-matrix-row1 {\r\n	background: #E9E9E9;\r\n	display: table-row;\r\n}\r\n.selected-text {\r\n	text-align: left;\r\n}\r\n.wdform-quantity {\r\n	width: 30px;\r\n	margin: 2px 0px;\r\n}\r\n.wdform_scale_rating label {\r\n	vertical-align: middle;\r\n}\r\n.ui-corner-all {\r\n	border-radius: 3px;\r\n}\r\n.ui-widget-content {\r\n	border: 0px;\r\n	background: transparent;\r\n}\r\na.ui-spinner-button:hover{\r\n	background: #FFB471 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-spinner-button:active{\r\n	background: #FFB471 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-spinner-button:focus{\r\n	background: #FFB471 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-slider-handle:hover{\r\n	background: #FFB471 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-slider-handle:active{\r\n	background: #FFB471 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-slider-handle:focus{\r\n	background: #FFB471 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\nui-state-hover {\r\n	background: #FFB471 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\n.ui-slider {\r\n	height: 6px;\r\n	background: #fff;\r\n	margin: 7px 0px;\r\n}\r\na.ui-slider-handle {\r\n	border-radius: 10px;\r\n	border: 2px solid #fff;\r\n	background: #A4A4A4;\r\n}\r\n.ui-slider-horizontal .ui-slider-handle {\r\n	top: -8px !important;\r\n}\r\n.ui-state-default{\r\n	border: 1px solid #d3d3d3;\r\n	background: #DFDDDD;\r\n	font-weight: normal;\r\n	color: #555555;\r\n}\r\n.ui-widget-content .ui-state-default{\r\n	border: 1px solid #d3d3d3;\r\n	background: #DFDDDD;\r\n	font-weight: normal;\r\n	color: #555555;\r\n}\r\n.ui-widget-header .ui-state-default {\r\n	border: 1px solid #d3d3d3;\r\n	background: #DFDDDD;\r\n	font-weight: normal;\r\n	color: #555555;\r\n}\r\n.ui-slider-range {\r\n	background: #A4A4A4 !important;\r\n}\r\n.wdform-page-and-images {\r\n	width: 100%;\r\n	border: 0px !important;\r\n}\r\n.paypal-property {\r\n	display: inline-block;\r\n	margin-right: 15px;\r\n	vertical-align: middle;\r\n}\r\n.sel-wrap {\r\n	display: inline-block;\r\n	vertical-align: middle;\r\n	width:100%;\r\n}\r\n.sel-wrap select {\r\n	position: absolute;\r\n z-index:-1;\r\n width: 0px !important;\r\n}\r\n.sel-imul {\r\n	display: inline-block;\r\n}\r\n.sel-imul .sel-selected {\r\n	cursor: pointer;\r\n	position: relative;\r\n	display: inline-block;\r\n	border-radius: 7px;\r\n	padding: 2px 0px 2px 2px;\r\n	font-size: 13px;\r\n	height: 26px;\r\n	line-height: 26px;\r\n	overflow: hidden;\r\n	background: #fff;\r\n	border: 1px solid #ccc;\r\n	bac