 Chrome10+,Safari5.1+ */\r\n	background: -o-linear-gradient(left, #00457F 1%, #0559A0 20%, #0E6AB8 80%, #006CC7 100%); /* Opera 11.10+ */\r\n	background: -ms-linear-gradient(left, #00457F 1%, #0559A0 20%, #0E6AB8 80%, #006CC7 100%); /* IE10+ */\r\nbackground: linear-gradient(to right, #00457F 1%, #0559A0 20%, #0E6AB8 80%, #006CC7 100%); /* W3C */\r\n	text-align: left;\r\n	padding: 7px 30px 10px 10px;\r\n	border-top-left-radius: 0px;\r\n	border-top-right-radius: 10px;\r\n	border-bottom-right-radius: 10px;\r\n	border-bottom-left-radius: 0px;\r\n	-moz-box-shadow: inset 51px 0px 8px -50px #636363, 4px 0px 7px 0px rgba(0, 0, 0, 0.23);\r\n	-webkit-box-shadow: inset 51px 0px 8px -50px #636363, 4px 0px 7px 0px rgba(0, 0, 0, 0.23);\r\n	box-shadow: inset 51px 0px 8px -50px #636363, 4px 0px 7px 0px rgba(0, 0, 0, 0.23);\r\ncolor:#fff;\r\nfont-size:18px;\r\n}\r\n\r\n.wdform_section_break {\r\n	margin: 16px 0px;\r\nfont-size:18px;\r\n}\r\n.wdform_section {\r\n	display: table-row;\r\n}\r\nselect {\r\n	border-radius: 7px;\r\n	height: 32px;\r\n	overflow: hidden;\r\n	border: 1px solid #ccc;\r\n	padding: 2px;\r\n	outline: none;\r\n}\r\ninput[type=\"text\"]{\r\n	border-radius: 7px;\r\n	height: 30px;\r\n	border: 1px solid #ccc;\r\n	padding:0 3px !important;\r\n}\r\ninput[type=\"password\"]{\r\n	border-radius: 7px;\r\n	height: 30px;\r\n	border: 1px solid #ccc;\r\n	padding:0 3px !important;\r\n}\r\ntextarea {\r\n	border-radius: 7px;\r\n	height: 30px;\r\n	border: 1px solid #ccc;\r\n	padding:0 3px !important;\r\n}\r\ninput[type=\"text\"]:focus{\r\n	border-color: #004D8E;\r\n	outline: none;\r\n}\r\n\r\ninput[type=\"password\"]:focus{\r\n	border-color: #004D8E;\r\n	outline: none;\r\n}\r\n\r\ntextarea:focus{\r\n	border-color: #004D8E;\r\n	outline: none;\r\n}\r\n\r\n\r\n.input_deactive {\r\n	color: #999999;\r\n	font-style: italic;\r\n}\r\n.input_active {\r\n	color: #000000;\r\n	font-style: normal;\r\n}\r\n.am_pm_select {\r\n	width: 70px;\r\n	vertical-align: middle;\r\n}\r\n.checkbox-div input[type=checkbox] {\r\n	position : absolute;\r\n	z-index: -1;\r\n}\r\n.checkbox-div {\r\n	width: 15px;\r\n	height: 16px;\r\n	background: #fff;\r\n	border: 1px solid #ccc;\r\n	border-radius: 5px;\r\n	position: relative;\r\n	display: inline-block;\r\n}\r\n.checkbox-div label {\r\n	cursor: pointer;\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=0)\";\r\n	filter: alpha(opacity=0);\r\n	opacity: 0;\r\n	content: \"\";\r\n	position: absolute;\r\n	width: 16px;\r\n	height: 13px;\r\n	background: url([SITE_ROOT]/images/01/checkbox.png);\r\n	border-radius: 2px;\r\n	top: 0px;\r\n	left: 2px;\r\n}\r\n.checkbox-div label:hover {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.checkbox-div .wdform-ch-rad-label:hover {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.wdform-ch-rad-label:hover + .checkbox-div label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=30)\";\r\n	filter: alpha(opacity=30);\r\n	opacity: 0.3;\r\n}\r\n.checkbox-div input[type=checkbox]:checked + label {\r\n	-ms-filter: \"progid:DXImageTransform.Microsoft.Alpha(Opacity=100)\";\r\n	filter: alpha(opacity=100);\r\n	opacity: 1;\r\n}\r\n.wdform-calendar-button,\r\n.wdform-calendar-button:hover {\r\n  display:inline-block;\r\n	background: transparent url([SITE_ROOT]/images/01/date.png) no-repeat left 50% !important;\r\n	border: 0px;\r\n	color: transparent;\r\n	width: 37px;\r\n	height: 30px;\r\n	position: relative;\r\n	left: -35px;\r\n	vertical-align: top;\r\n}\r\n.wdform-calendar-button:focus {\r\n outline:none; \r\n}\r\n.wdform-calendar-button:focus {\r\n	outline:none;\r\n}\r\n.radio-div input[type=radio] {\r\n	position : absolute;\r\n	z-index: -1;\r\n}\r\n.forlabs {\r\n	float: right;\r\n	margin-right: 20px;\r\n}\r\n.radio-div {\r\n	width: 15px;\r\n	height: 16px;\r\n	background: #fff;\r\n	border: 1px solid #ccc;\r\n	borde