\n	color: #000\r\n}\r\n.wdform_separator {\r\n	font-style: bold;\r\n	vertical-align: middle;\r\n	color: #000;\r\n}\r\n.wdform_line {\r\n	color: #000\r\n}\r\n.wdform-required {\r\n	border: none;\r\n	color: red;\r\n	vertical-align: top;\r\n}\r\n.captcha_img {\r\n	border-width: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	cursor: pointer;\r\n	border-radius: 7px;\r\n}\r\n.captcha_refresh {\r\n	width: 30px;\r\n	height: 30px;\r\n	border-width: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	vertical-align: middle;\r\n	cursor: pointer;\r\n	background-image: url([SITE_ROOT]/images/refresh_black.png);\r\n}\r\n.captcha_input {\r\n	height: 20px;\r\n	border-width: 1px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	vertical-align: middle;\r\n}\r\n.file_upload {\r\n	border: 0px solid white;\r\n	border-radius: 0px;\r\n	margin: 0px;\r\n	padding: 0px;\r\n	color: black;\r\n	background-color: white;\r\n}\r\n.page_deactive {\r\n	font-size: 12px;\r\n color: #0D5492;\r\n	cursor: pointer;\r\n	background-color: #7FA6C6;\r\n	margin: 1px;\r\n	display: inline-block;\r\n	height: 20px;\r\n	text-align: center;\r\n	vertical-align: bottom;\r\n	padding-top: 5px;\r\n	padding: 5px 30px 0px 30px;\r\n}\r\n.page_active {\r\n	color: #fff;\r\n	cursor: pointer;\r\n	background-color: #004D8E;\r\n	margin: 1px;\r\n	display: inline-block;\r\n	vertical-align: bottom;\r\n	height: 25px;\r\n	text-align: center;\r\n	padding: 5px 30px 0px 30px;\r\n}\r\n.page_percentage_active {\r\n	padding: 0px;\r\n	margin: 0px;\r\n	border-spacing: 0px;\r\n	height: 25px;\r\n	line-height: 25px;\r\n	border-top-left-radius: 17px;\r\n	font-size: 15px;\r\n	float: left;\r\n	text-align: right !important;\r\n	z-index: 1;\r\n	position: relative;\r\n	background: #00559D ; /* Old browsers */\r\n	background: -moz-linear-gradient(left, #00559D 0%, #005BA7 67%, #00559D 100%); /* FF3.6+ */\r\n	background: -webkit-gradient(linear, left top, right top, color-stop(0%, #00559D ), color-stop(67%, #005BA7 ), color-stop(100%, #00559D )); /* Chrome,Safari4+ */\r\n	background: -webkit-linear-gradient(left, #00559D 0%, #005BA7 67%, #00559D 100%); /* Chrome10+,Safari5.1+ */\r\n	background: -o-linear-gradient(left, #00559D 0%, #005BA7 67%, #00559D 100%); /* Opera 11.10+ */\r\n	background: -ms-linear-gradient(left, #00559D 0%, #005BA7 67%, #00559D 100%); /* IE10+ */\r\nbackground: linear-gradient(to right, #00559D 0%, #005BA7 67%, #00559D 100%);\r\n	vertical-align: middle;\r\n}\r\n.page_percentage_deactive {\r\n	height: 25px;\r\n	line-height: 25px;\r\n	background-color: #7FA6C6;\r\n	text-align: left !important;\r\n	margin-bottom: 1px;\r\n	border-top-left-radius: 17px;\r\n	border-top-right-radius: 17px;\r\n}\r\n.page_numbers {\r\n	font-size: 14px;\r\n	color: #000;\r\n}\r\n.phone_area_code {\r\n	width: 50px;\r\n}\r\n.phone_number {\r\n	width: 100px;\r\n}\r\nbutton {\r\n	cursor: pointer;\r\n}\r\n.other_input {\r\n	border-radius: 0px;\r\n	border-width: 1px;\r\n	height: 16px;\r\n	font-size: 12px;\r\n	padding: 1px;\r\n	margin: 1px;\r\n	margin-left: 25px;\r\n	z-index: 100;\r\n	position: absolute;\r\n}\r\n.wdform_page_navigation {\r\n	text-align: right !important;\r\n	margin-bottom: 0px;\r\n}\r\n.wdform_page_navigation span:first-child {\r\n	border-top-left-radius: 17px;\r\n}\r\n.wdform_percentage_arrow {\r\ndisplay: inline-block;\r\nwidth: 21px;\r\nheight: 25px;\r\nbackground-color: #0057A0;\r\nposition: relative;\r\nleft: -15px;\r\nz-index: 0;\r\nvertical-align: middle;\r\n-moz-transform: scale(1) rotate(0deg) translateX(0px) translateY(0px) skewX(-10deg) skewY(0deg);\r\n-webkit-transform: scale(1) rotate(0deg) translateX(0px) translateY(0px) skewX(-25deg) skewY(0deg);\r\n-o-transform: scale(1) rotate(0deg) translateX(0px) translateY(0px) skewX(-10deg) skewY(0deg);\r\n-ms-transform: scale(1) rotate(0deg) translateX(0px) translateY(0px) skewX(-10deg) skewY(0deg);\r\ntransform: scale(1) rotate(0deg) translateX(0px) translateY(0px) skewX(-10deg) skewY(0deg);\r\n}\r\n.wdform_percentage_text {\r\n	margin: 3px -14px 3px 9px;\r\n	color: #FFFFFF;\r\n	font-weight: bold;\r\n}\r\n.wdform_percentage_title {\r\n	color: #000000;\r\n	font-style: italic;\r\n	margin: 0px 0px 0px 40px;\r\n	display: inline-block;\r\n	line-height: 25px;\r\n	height: 25px;\r\n	vertical-align: middle;\r\n}\r\n.wdform_map {\r\n	border: 6px solid #fff;\r\n}\r\n.wdform_button button {\r\n	background: #e4e4e4; /* Old browsers */\r\n	background: -moz-linear-gradient(top, #e4e4e4 0%, #cccccc 100%); /* FF3.6+ */\r\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%, #e4e4e4), color-stop(100%, #cccccc)); /* Chrome,Safari4+ */\r\n	background: -webkit-linear-gradient(top, #e4e4e4 0%, #cccccc 100%); /* Chrome10+,Safari5.1+ */\r\n	background: -o-linear-gradient(top, #e4e4e4 0%, #cccccc 100%); /* Opera 11.10+ */\r\n	background: -ms-linear-gradient(top, #e4e4e4 0%, #cccccc 100%); /* IE10+ */\r\n	background: linear-gradient(to bottom, #e4e4e4 0%, #cccccc 100%); /* W3C */\r\n	cursor: pointer;\r\n	font-size: 17px;\r\n	border-radius: 7px;\r\n	min-width: 80px;\r\n	min-height: 27px;\r\n	color: #787878;\r\n	border: 0px;\r\n	margin: 5px;\r\n	box-shadow: 0px 0px 2px #c9c9c9;\r\n	font-family: Segoe UI;\r\n}', 0);
INSERT INTO `wp_formmaker_themes` (`id`, `title`, `css`, `default`) VALUES
(37, 'Theme 10 green', '.wdform-page-and-images .other_input\r\n{\r\nmax-width: none;\r\n}\r\nbutton,\r\ninput,\r\nselect,\r\ntextarea\r\n{\r\nfont-size:14px;\r\n}\r\n.warning,\r\n.error\r\n{\r\nbackground-color: #D8E5DB;\r\nborder: 1px solid #007616;\r\nmargin-bottom: 10px;\r\ncolor: #007616;\r\npadding: 5px;\r\n}\r\n.warning *,\r\n.error *\r\n{\r\nmargin:0;\r\n}\r\n.recaptcha_input_area input\r\n{\r\nheight:initial !important;\r\n}\r\n.wdform_grading input {\r\n	width: 100px;\r\n}\r\n.wdform-matrix-cell input[type=\"text\"] {\r\n	width: 100px;\r\n}\r\n.wdform-matrix-cell select {\r\n	width: 60px;\r\n}\r\n.wdform_section .wdform_column:last-child {\r\n	padding-right: 0px !important;\r\n}\r\n.wdform_preload {\r\n	display: none;\r\n	content: url([SITE_ROOT]/images/01/03/next_hoverbg.png) url([SITE_ROOT]/images/01/03/previous_hover.png) url([SITE_ROOT]/images/01/03/next_hover.png);\r\n}\r\n.wdform_grading {\r\n	padding: 3px 0px;\r\n}\r\n.wdform-matrix-table {\r\n	display: table;\r\n	border-spacing: 0px;\r\n}\r\n.wdform-matrix-column {\r\n	text-align: left;\r\n	display: table-cell;\r\n}\r\n.wdform-matrix-cell {\r\n	text-align: center;\r\n	display: table-cell;\r\n	padding: 6px 10px;\r\n}\r\n.wdform-matrix-head>div {\r\n	display: table-cell;\r\n	text-align: center;\r\n}\r\n.wdform-matrix-head {\r\n	display: table-row;\r\n}\r\n.wdform-matrix-row0 {\r\n	background: #DFDFDF;\r\n	display: table-row;\r\n}\r\n.wdform-matrix-row1 {\r\n	background: #E9E9E9;\r\n	display: table-row;\r\n}\r\n.selected-text {\r\n	text-align: left;\r\n}\r\n.wdform-quantity {\r\n	width: 30px;\r\n	margin: 2px 0px;\r\n}\r\n.wdform_scale_rating label {\r\n	vertical-align: middle;\r\n}\r\n.ui-corner-all {\r\n	border-radius: 3px;\r\n}\r\n.ui-widget-content {\r\n	border: 0px;\r\n	background: transparent;\r\n}\r\na.ui-spinner-button:hover{\r\n	background: #006C14 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-spinner-button:active{\r\n	background: #006C14 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-spinner-button:focus{\r\n	background: #006C14 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-slider-handle:hover{\r\n	background: #006C14 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-slider-handle:active{\r\n	background: #006C14 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\na.ui-slider-handle:focus{\r\n	background: #006C14 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\nui-state-hover {\r\n	background: #006C14 !important;\r\n	color: #fff;\r\n	outline: none;\r\n}\r\n.ui-slider {\r\n	height: 6px;\r\n	background: #fff;\r\n	margin: 7px 0px;\r\n}\r\na.ui-slider-handle {\r\n	border-radius: 10px;\r\n	border: 2px solid #fff;\r\n	background: #A4A4A4;\r\n}\r\n.ui-slider-horizontal .ui-slider-handle {\r\n	top: -8px !important;\r\n}\r\n.ui-state-default{\r\n	border: 1px solid #d3d3d3;\r\n	background: #DFDDDD;\r\n	font-weight: normal;\r\n	color: #555555;\r\n}\r\n.ui-widget-content .ui-state-default{\r\n	border: 1px solid #d3d3d3;\r\n	background: #DFDDDD;\r\n	font-weight: normal;\r\n	color: #555555;\r\n}\r\n.ui-widget-header .ui-state-default {\r\n	border: 1px solid #d3d3d3;\r\n	background: #DFDDDD;\r\n	font-weight: normal;\r\n	color: #555555;\r\n}\r\n.ui-slider-range {\r\n	background: #A4A4A4 !important;\r\n}\r\n.wdform-page-and-images {\r\n	width: 100%;\r\n	border: 0px !important;\r\n}\r\n.paypal-property {\r\n	display: inline-block;\r\n	margin-right: 15px;\r\n	vertical-align: middle;\r\n}\r\n.sel-wrap {\r\n	display: inline-block;\r\n	vertical-align: middle;\r\n	width:100%;\r\n}\r\n.sel-wrap select {\r\n	position: absolute;\r\n z-index:-1;\r\n width: 0px !important;\r\n}\r\n.sel-imul {\r\n	display: inline-block;\r\n}\r\n.sel-imul .sel-selected {\r\n	cursor: pointer;\r\n	position: relative;\r\n	display: inline-block;\r\n	border-radius: 7px;\r\n	padding: 2px 0px 2px 2px;\r\n	font-size: 13px;\r\n	height: 26px;\r\n	line-height: 26px;\r\n	overflow: hidden;\r\n	background: #fff;\r\n	border: 1px solid #ccc;\r\n	background-position: right 2px center;\r\n	width: 100%;\r\n}\r\n.sel-imul.act .sel-selected {\r\n	background: #fff;\r\n}\r\n.sel-selected .sel-arraw {\r\n	height: 28px;\r\n	width: 32px;\r\n	background: url([SITE_ROOT]/images/01/01.png) 50% 50% no-repeat;\r\n	position: absolute;\r\n	top: 0px;\r\n	right: 0px;\r\n	padding: 1px;\r\n}\r\n.sel-imul:hover .sel-selected .sel-arraw {\r\n// background-color:#e0e0e0;\r\n// border-left:1px solid #bbb;\r\n}\r\n.sel-imul.act .sel-selected .sel-arraw {\r\n// background-color:#e0e0e0;\r\n// border-left:1px solid #bbb;\r\n}\r\n.sel-imul .sel-options {\r\n	background: #fff;\r\n	border: 1px solid #dbdbdb;\r\n	border-top: none;\r\n	position: absolute;\r\n	width: inherit;\r\n	display: none;\r\n	z-index: 10;\r\n	max-height: 200px;\r\n	overflow-y: auto;\r\n	overflow-x: hidden;\r\n}\r\n.sel-options .sel-option {\r\n	padding: 3px 4px;\r\n	font-size: 13px;\r\n	border: 1px solid #fff;\r\n	border-right: none;\r\n	border-left: none;\r\n	text-align: left;\r\n}\r\n.sel-options .sel-option:hover {\r\n	border-color: #dbdbdb;\r\n	cursor: pointer;\r\n}\r\n.sel-options .sel-option.sel-ed {\r\n	background: #dbdbdb;\r\n	border-color: #dbdbdb;\r\n}\r\ninput[type=text] {\r\n	margin: 0px;\r\n}\r\ninput[type=password] {\r\n	margin: 0px;\r\n}\r\ninput[type=url] {\r\n	margin: 0px;\r\n}\r\ninput[type=email] {\r\n	margin: 0px;\r\n}\r\ninput.text {\r\n	margin: 0px;\r\n}\r\ninput.title {\r\n	margin: 0px;\r\n}\r\ntextarea {\r\n	margin: 0px;\r\n}\r\nselect {\r\n	margin: 0px;\r\n}\r\n.form-error {\r\n	border-color: red !important;\r\n}\r\n.form-error:focus {\r\n	border-color: red !important;\r\n}\r\n.wdform-page-and-images:after {\r\n	width: 100%;\r\n	content: \"\";\r\n	display: block;\r\n	height: 17px;\r\n	background: url([SITE_ROOT]/images/01/0.png) no-repeat center center;\r\n	position: relative;\r\n	background-size: cover;\r\n	top: -17px;\r\n	left: -50px;\r\n	padding-left: 100px;\r\n}\r\n.wdform-field {\r\n	display: table-cell;\r\n	padding: 5px 0px;\r\n}\r\n.wdform-label-section{\r\n	text-align: left;\r\n	display: table-cell;\r\n}\r\n.wdform-element-section {\r\n	text-align: left;\r\n	display: table-cell;\r\n	min-width: 140px;\r\n}\r\n.file-upload input {\r\n	position: absolute;\r\n	visibility: hidden;\r\n}\r\n.file-upload-status {\r\n	margin-left: 10px;\r\n	max-width: 200px;\r\n	font-weight: bold;\r\n	font-size: 16px;\r\n	color: #888;\r\n	background: #fff;\r\n	position: absolute;\r\n	border-radius: 7px;\r\n	height: 27px;\r\n	border: 1px solid #ccc;\r\n	padding-left: 5px;\r\n	padding-right: 5px;\r\n	white-space: nowrap;\r\n	overflow: hidden;\r\n	direction: rtl;\r\n//text-overflow: ellipsis;\r\n}\r\n.file-picker {\r\n	width: 38px;\r\n	height: 34px;\r\n	background: url([SITE_ROOT]/images/01/upload.png);\r\n	display: inline-block;\r\n}\r\ndiv.wdform-page-button {\r\n	color: #414141;\r\n	cursor: pointer;\r\n	display: inline-block;\r\n	height: 36px;\r\n	line-height: 36px;\r\n	background: url([SITE_ROOT]/images/01/nextbg.png) no-repeat right center;\r\n	-webkit-background-size: cover;\r\n	-moz-background-size: cover;\r\n	-o-background-size: cover;\r\n	background-size: cover;\r\n	border-style: solid;\r\n	padding: 0px 15px;\r\n	vertical-align: middle;\r\n	border-color: transparent;\r\n}\r\ndiv.wdform-page-button:hover {\r\n	background: url([SITE_ROOT]/images/01/03/next_hoverbg.png) no-repeat right center;\r\n	-webkit-background-size: cover;\r\n	-moz-background-size: cover;\r\n	-o-background-size: cover;\r\n	background-size: cover;\r\ncolor:#fff;\r\n}\r\n.next-page div.wdform-page-button {\r\n	border-width: 0px 18px 0px 0px;\r\n	-moz-border-image: url([SITE_ROOT]/images/01/next.png) 0 36 0 0 stretch;\r\n	-webkit-border-image: url([SITE_ROOT]/images/01/next.png) 0 36 0 0 stretch;\r\n	-o-border-image: url([SITE_ROOT]/images/01/next.png) 0 36 0 0 stretch;\r\n	border-image: url([SITE_ROOT]/images/01/next.png) 0 36 0 0 stretch;\r\n	box-shadow: inset 51px 0px 8px -50px #636363;\r\n}\r\n.next-page div.wdform-page-button:hover {\r\n	-moz-borde