5D\"][vc_custom_heading text=\"ПРИСОЕДИНЯЙТЕСЬ К НАМ В СОЦИАЛЬНЫХ СЕТЯХ\" font_container=\"tag:h6|font_size:14px|text_align:center|line_height:14px\" google_fonts=\"font_family:Roboto%20Condensed%3A300%2C300italic%2Cregular%2Citalic%2C700%2C700italic|font_style:300%20light%20regular%3A300%3Anormal\" css=\".vc_custom_1475519743403{margin-bottom: 2px !important;}\"][us_social_links size=\"13px\" align=\"center\" facebook=\"https://www.facebook.com/mebelnaya.masterskaya.kraftman\" twitter=\"https://twitter.com/kraftman_ru\" google=\"#\" linkedin=\"https://www.linkedin.com/profile/view?id=354034275\" youtube=\"https://www.youtube.com/channel/UCrb6lmDzibRzYVzWHDhMn_A\" instagram=\"https://www.instagram.com/kraftman.ru/\" vk=\"https://vk.com/kraftmanru\" tumblr=\"https://www.tumblr.com/blog/kraftman-ru\" odnoklassniki=\"https://ok.ru/profile/559989029759\"][us_separator type=\"invisible\"][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2016-10-11 17:08:51', '2016-10-11 14:08:51', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0);
