INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1776, 1, '2016-11-01 00:02:00', '2016-10-31 21:02:00', '[vc_row][vc_column][vc_column_text]\r\n<div id=\"docs-primary-toolbars\" class=\"docs-collapsable-toolbar\">\r\n<div id=\"docs-toolbar\" class=\"goog-toolbar ie8\" tabindex=\"0\">\r\n<div id=\"t-print\" class=\"goog-toolbar-button goog-inline-block goog-toolbar-button-ie\" data-tooltip=\"Print (Ctrl+P)\">\r\n<div class=\"goog-toolbar-button-outer-box goog-inline-block\">\r\n<div class=\"goog-toolbar-button-inner-box goog-inline-block\">\r\n<div class=\"docs-icon goog-inline-block \">\r\n<div class=\"docs-icon-img-container docs-icon-img docs-icon-print\">\r\n<div id=\"docs-chrome\" tabindex=\"0\">\r\n<div id=\"docs-additional-bars\">\r\n<div id=\"waffle-editorsized-bar\">\r\n<div id=\"formula-bar\">\r\n<div id=\"t-formula-bar-input-container\">\r\n<div dir=\"ltr\">\r\n<div id=\"t-formula-bar-input\" spellcheck=\"false\">\r\n<div class=\"cell-input\" dir=\"ltr\" tabindex=\"0\" contenteditable=\"true\">Кожаный диван комфортный, но требует обивки кожей или перетяжки? Выездной оценщик доставит каталоги мебельной кожи на дом, а мастера Крафтман перетянут мебель из кожи в кратчайшие сроки. Мы уже выполнили работы для клиентов с лидирующими мировыми брендами они довольны выполненной работой и рекомендуют нас!</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"2/3\"][vc_row_inner][vc_column_inner width=\"1/2\"][ultimate_fancytext fancytext_align=\"left\" strings_textspeed=\"35\" strings_backspeed=\"0\" fancytext_strings=\"БЫЛО\"][us_single_image image=\"211\" size=\"medium\" align=\"center\" lightbox=\"1\"][us_single_image image=\"213\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][vc_column_inner width=\"1/2\"][ultimate_fancytext fancytext_align=\"left\" strings_textspeed=\"35\" strings_backspeed=\"0\" fancytext_strings=\"СТАЛО\"][us_single_image image=\"212\" size=\"medium\" align=\"center\" lightbox=\"1\"][us_single_image image=\"214\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][/vc_row_inner][/vc_column][vc_column width=\"1/3\"][vc_column_text]\r\n<h4>Перетяжка мебели кожей.</h4>\r\n[/vc_column_text][vc_column_text]\r\n<p style=\"text-align: justify;\">Для перетяжки мягкой мебели из кожи требуются мастера обученные этой задаче для того что бы не было складок и других изъянов перетяжки. После замены реставраторами ЛКП, мастера занялись перетяжкой мебели кожей на дому. Требуется заменить обивку мебели с ткани на кожу? Для этого изменим крой, учитывая разницу растяжения материалов. В результате сложные элементы мебели обтянуты кожей без изъянов и складок. Мы используем только специальную кожу для мебели, цена рассчитывается с учетом сложности работы и категории кожи.</p>\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"2/3\"][vc_row_inner][vc_column_inner width=\"1/2\"][ultimate_fancytext fancytext_align=\"left\" strings_textspeed=\"35\" strings_backspeed=\"0\" fancytext_strings=\"БЫЛО\"][us_single_image image=\"208\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][vc_column_inner width=\"1/2\"][ultimate_fancytext fancytext_align=\"left\" strings_textspeed=\"35\" strings_backspeed=\"0\" fancytext_strings=\"СТАЛО\"][us_single_image image=\"209\" size=\"medium\" align=\"center\" lightbox=\"1\"][us_single_image image=\"210\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][/vc_row_inner][/vc_column][vc_column width=\"1/3\"][vc_column_text]\r\n<h4>Перетяжка дивана кожей.</h4>\r\n[/vc_column_text][vc_column_text]\r\n<p style=\"text-align: justify;\">Над корректировкой и изменением кроя, в ходе перетяжки дивана из ткани в лицевую кожу, поработал технолог. Изменив размеры кроя, из-за разницы в растяжении кожи и ткани, он дополнил крой декоративными отстрочками с увеличенным шагом, затем мастер обтянул диван кожей. Перетяжка дивана из кожи в Москве на дому выполняется при несложном крое. Если осложняющие факторы обивки не позволят выполнить работу по перетяжке на дому то  диван заберут для обивки в цех. Сколько стоит перетянуть диван кожей? Цена перетяжки дивана складывается из факторов сложности: сложные элементы кроя, дополнительная отстрочка, цена и качество мебельной кожи, транспортировка дивана в цех и обратно.</p>\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"2/3\"][vc_row_inner][vc_column_inner width=\"1/2\"][ultimate_fancytext fancytext_align=\"left\" strings_textspeed=\"35\" strings_backspeed=\"0\" fancytext_strings=\"БЫЛО\"][us_single_image image=\"194\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][vc_column_inner width=\"1/2\"][ultimate_fancytext fancytext_align=\"left\" strings_textspeed=\"35\" strings_backspeed=\"0\" fancytext_strings=\"СТАЛО\"][us_single_image image=\"195\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][/vc_row_inner][/vc_column][vc_column width=\"1/3\"][vc_column_text]\r\n<h4>Перетяжка кресла кожей.</h4>\r\n[/vc_column_text][vc_column_text]\r\n<p style=\"text-align: justify;\">Перетянуть кожаное кресло не проще чем диван. Во время работы приходится решать те же задачи что бы не было складок и других изъянов. Мастера перетянут кожаные кресла на дому или заберут для обивки или перетяжки в нашу мастерскую. Срок перетяжки кожаных кресел занимает 2 дня но может увеличится и до нескольких недель при сложном крое или других факторах сложности работ. Перетяжка кресел кожей позволит использовать любимые кресла еще много лет. После перетяжки кресла выглядят как новые.</p>\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row columns_type=\"none\" height=\"auto\" width=\"full\" css=\".vc_custom_1476205264435{margin-top: -20px !important;}\"][vc_column width=\"1/4\" offset=\"vc_hidden-sm vc_hidden-xs\"][us_separator type=\"invisible\" size=\"small\"][/vc_column][vc_column width=\"3/4\" css=\".vc_custom_1476217390778{padding-top: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-align: left;\">[iphorm id=\"5\" name=\"ЗАПРОС\"]</p>\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ultimate_carousel slider_type=\"full_width\" slide_to_scroll=\"single\" autoplay_speed=\"1300\" adaptive_height=\"on\"][interactive_banner_2 banner_title=\"Перетяжка мягкой мебели\" banner_desc=\"Подробнее о перетяжке мягкой мебели ...\" heading_tag=\"h3\" banner_image=\"id^223|url^http://kraftman.ru/wp-content/uploads/2016/02/peretyajka-myakgoj-combine1-s.jpg|caption^null|alt^null|title^peretyajka-myakgoj-combine1-s|description^null\" banner_link=\"url:http%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|title:%D1%80%D0%B5%D0%BC%D0%BE%D0%BD%D1%82%20%D0%BC%D0%B5%D0%B1%D0%B5%D0%BB%D0%B8|\" banner_style=\"style6\" banner_color_bg=\"#72006d\" image_opacity=\"1\" image_opacity_on_hover=\"0.3\"][interactive_banner_2 banner_title=\"Перетяжка мебели\" banner_desc=\"Подробнее о перетяжке мебели ...\" heading_tag=\"h3\" banner_image=\"id^204|url^http://kraftman.ru/wp-content/uploads/2016/02/peretyajka-garnitur-hitech-1-s.jpg|caption^null|alt^null|title^peretyajka-garnitur-hitech-1-s|description^null\" banner_link=\"url:http%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|title:%D1%80%D0%B5%D0%BC%D0%BE%D0%BD%D1%82%20%D0%BC%D0%B5%D0%B1%D0%B5%D0%BB%D0%B8|\" banner_style=\"style6\" banner_color_bg=\"#72006d\" image_opacity=\"1\" image_opacity_on_hover=\"0.3\"][interactive_banner_2 banner_title=\"Перетяжка дивана\" banner_desc=\"Подробнее о перетяжке дивана ...\" heading_tag=\"h3\" banner_image=\"id^187|url^http://kraftman.ru/wp-content/uploads/2016/02/peretyajka-divan-upgrade1-s.jpg|caption^null|alt^null|title^peretyajka-divan-upgrade1-s|description^null\" banner_link=\"url:http%3A%2F%2Fkraftman.