\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"МАТЕРИАЛЫ\" thumb_img=\"id^1670|url^https://kraftman.ru/wp-content/uploads/2016/10/tkani_s.png|caption^null|alt^МАТЕРИАЛЫ|title^МАТЕРИАЛЫ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fmaterialy%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"О КОМПАНИИ\" thumb_img=\"id^1659|url^https://kraftman.ru/wp-content/uploads/2016/10/kraftman_s.png|caption^null|alt^О КОМПАНИИ|title^О КОМПАНИИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fo-kompanii%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row height=\"auto\" el_id=\"brand\"][vc_column][vc_custom_heading text=\"ОТЗЫВЫ\" font_container=\"tag:h6|font_size:14px|text_align:left|line_height:14px\" google_fonts=\"font_family:Roboto%20Condensed%3A300%2C300italic%2Cregular%2Citalic%2C700%2C700italic|font_style:300%20light%20regular%3A300%3Anormal\" css=\".vc_custom_1520339921763{margin-bottom: 2px !important;}\"][us_logos columns=\"5\" with_indents=\"1\" orderby=\"rand\" arrows=\"1\" auto_scroll=\"1\" interval=\"3\" items=\"%5B%7B%22image%22%3A%22440%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fharry-winston-mercury-ralph-laurent%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22438%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Flukojl%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22441%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fhotel-metropol-moscow%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22433%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Famerikanskaya-torgovaya-palata%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22435%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Ffski%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22434%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fotel-borodino%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22439%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fmcdonalds%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22443%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fthe-ritz-carlton%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22442%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fradiostantsiya-serebryanyj-dozhd%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22444%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fhotel-savoy-moscow%7C%7C%7C%22%7D%5D\"][us_separator type=\"invisible\"][/vc_column][/vc_row][vc_row height=\"auto\" width=\"full\" css=\".vc_custom_1520334013097{margin-top: -20px !important;}\"][vc_column width=\"1/6\" offset=\"vc_hidden-sm vc_hidden-xs\"][us_separator type=\"invisible\" size=\"small\"][/vc_column][vc_column width=\"2/3\" css=\".vc_custom_1476217390778{padding-top: 0px !important;}\"][us_btn text=\"Оставить отзыв\" link=\"url:%23leave_feedback_form|title:%D0%9E%D1%81%D1%82%D0%B0%D0%B2%D0%B8%D1%82%D1%8C%20%D0%BE%D1%82%D0%B7%D1%8B%D0%B2||\" align=\"center\" el_class=\"fancybox\"][vc_column_text]\r\n<p style=\"text-align: left;\">[iphorm id=\"5\" name=\"ЗАПРОС\"]</p>\r\n[/vc_column_text][vc_column_text]Мы с радостью ответим на все ваши вопросы![/vc_column_text][/vc_column][vc_column width=\"1/6\"][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-03-15 19:54:58', '2018-03-15 16:54:58', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
