ablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"МАТЕРИАЛЫ\" thumb_img=\"id^1670|url^https://kraftman.ru/wp-content/uploads/2016/10/tkani_s.png|caption^null|alt^МАТЕРИАЛЫ|title^МАТЕРИАЛЫ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fmaterialy%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"О КОМПАНИИ\" thumb_img=\"id^1659|url^https://kraftman.ru/wp-content/uploads/2016/10/kraftman_s.png|caption^null|alt^О КОМПАНИИ|title^О КОМПАНИИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fo-kompanii%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row][vc_row height=\"auto\" el_id=\"brand\"][vc_column][vc_custom_heading text=\"ОТЗЫВЫ\" font_container=\"tag:h6|font_size:14px|text_align:left|line_height:14px\" google_fonts=\"font_family:Roboto%20Condensed%3A300%2C300italic%2Cregular%2Citalic%2C700%2C700italic|font_style:300%20light%20regular%3A300%3Anormal\" css=\".vc_custom_1520339921763{margin-bottom: 2px !important;}\"][us_logos columns=\"5\" with_indents=\"1\" orderby=\"rand\" arrows=\"1\" auto_scroll=\"1\" interval=\"3\" items=\"%5B%7B%22image%22%3A%22440%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fharry-winston-mercury-ralph-laurent%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22438%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Flukojl%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22441%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fhotel-metropol-moscow%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22433%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Famerikanskaya-torgovaya-palata%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22435%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Ffski%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22434%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fotel-borodino%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22439%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fmcdonalds%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22443%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fthe-ritz-carlton%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22442%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fradiostantsiya-serebryanyj-dozhd%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22444%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fhotel-savoy-moscow%7C%7C%7C%22%7D%5D\"][us_separator type=\"invisible\"][/vc_column][/vc_row][vc_row height=\"auto\" width=\"full\" css=\".vc_custom_1520334013097{margin-top: -20px !important;}\"][vc_column width=\"1/6\" offset=\"vc_hidden-sm vc_hidden-xs\"][us_separator type=\"invisible\" size=\"small\"][/vc_column][vc_column width=\"2/3\" css=\".vc_custom_1476217390778{padding-top: 0px !important;}\"][us_btn text=\"Оставить отзыв\" link=\"url:%23leave_feedback_form|title:%D0%9E%D1%81%D1%82%D0%B0%D0%B2%D0%B8%D1%82%D1%8C%20%D0%BE%D1%82%D0%B7%D1%8B%D0%B2||\" align=\"center\" el_class=\"fancybox\"][vc_column_text]\r\n<p style=\"text-align: left;\">[iphorm id=\"5\" name=\"ЗАПРОС\"]</p>\r\n<h2>\r\nВдохните в любимую мебель с историей новую жизнь\r\n</h2>\r\n<p>\r\nКогда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели.\r\n</p>\r\n<p>\r\nНа этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все  детали, элементы декора, особенности кроя.\r\n</p>\r\n<p>\r\nКрафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. \r\n</p>\r\n<p>\r\nСпециалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.\r\n</p>\r\n<h2>\r\nЭтапы работы \r\n</h2>\r\n<h3>\r\nВыезд дизайнера\r\n</h3>\r\n<p>\r\nПредставитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.\r\n</p>\r\n<h3>\r\nСогласование обивочного материала\r\n</h3>\r\n<p>\r\nЕсли вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.\r\n</p>\r\n<h3>\r\nСогласование дат транспортировки\r\n</h3>\r\n<p>\r\nПосле того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.\r\n</p>\r\n<h3>\r\nВозврат перетянутой мебели\r\n</h3>\r\n<p>\r\nСпустя две недели мы привозим мебель  обратно в ее  новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.\r\n</p>\r\n<h2>\r\nПреимущества работы с Крафтман\r\n</h2>\r\n<ul>\r\n<li>\r\nКомпания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты. \r\n</li>\r\n<li>\r\nСобственная служба доставки.\r\n</li>\r\n<li>\r\nВозможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.\r\n</li>\r\n<li>\r\nРасширенный срок гарантии на выполненные работы - 3 года.\r\n</li>\r\n<li>\r\nКаждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.\r\n</li>\r\n<li>\r\nКачественная перетяжка мебели и выгодные цены.\r\n</li>\r\n<li>\r\nОпыт работы с 1986 года.\r\n</li>\r\n<li>\r\nКомпания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.\r\n</li>\r\n<li>\r\nОценить фото выполненных работ можно в нашем портфолио.\r\n</li>\r\n</ul>\r\n<p>\r\nВы еще думаете? Скорее возьмите телефон и звоните!\r\n</p>\r\n[/vc_column_text][vc_column_text]Мы с радостью ответим на все ваши вопросы![/vc_column_text][/vc_column][vc_column width=\"1/6\"][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-03-21 08:32:20', '2018-03-21 05:32:20', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
(2104, 0, '2018-03-21 11:57:49', '0000-00-00 00:00:00', 'Проверяем схему - Международная Система Контроля IP Адресов \r\nhttp://bit.ly/2GcvCQk', 'Проверяем схему - Международная Система Контроля IP Адресов', '', 'pending', 'closed', 'closed', '', '', '', '', '2018-03-21 11:57:49', '0000-00-00 00:00:00', '', 0, 'https://kraftman.ru/?p=2104', 0, 'feedback_new', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(2105, 1, '2018-03-21 12:11:24', '2018-03-21 09:11:24', '[vc_row][vc_column][vc_column_text]\r\n<div class=\"line\"></div>\r\n<div class=\"wrapper_s\">\r\n<div class=\"questions\">\r\n\r\nПрофессиональный ремонт мебели в Москве и Московской области: перетяжка мягкой обивки диванов — недорого перетянем тканью, перешьем либо частично поменяем.\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/1.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/2.jpg\" /></div>\r\n<h2>Профессиональная перетяжка обшивки диванов в Москве и МО</h2>\r\nДиван — будь он угловым, трансформером, с подлокотниками, пр. — ч предмет в приемной руководителя, гостиной квартиры или дома. Годы и популярность не щадят его обивку. Ветшая, она лишает привлекательности меблировку и губит имидж помещения. Но и избавляться от добротной вещи, которая еще могла бы послужить — верх расточительства. Рациональный выход из ситуации — перетяжка дивана. Профессионалы мебельной мастерской «Крафтман» в корне изменят вид обветшавшего изделия (с фото можно ознакомиться в этом и других разделах сайта). Высшее качество обходится не дешево, но оно того стоит!\r\n<h2>Перетяжка обивки или ремонт дивана?</h2>\r\nКогда на обтяжке появляются потертости и прорехи, первая мысль, которая посещает владельцев, это — перетянуть диван. Рекомендуем заказать услугу у настоящих мастеров «диванных дел». В нашей мебельной мастерской — только такие!\r\n\r\nНа первичном осмотре оценщик может вскрыть малоприятные нюансы:\r\n<ul>\r\n 	<li>Потерял потребительские качества и пришел в негодность наполнитель;</li>\r\n 	<li>Одна или несколько ножек держатся на честном слове, их целесообразно заменить;</li>\r\n 	<li>Износились и требуют замены металлические детали трансформирующего механизма, пр.</li>\r\n</ul>\r\nВ таком случае не обойтись без основательного <a href=\"http://kraftman.ru/portfolio/remont-divanov/\">ремонта диванов</a>.\r\nПоследний, в свою очередь, чреват не меньшими «сюрпризами».\r\n<div class=\"sofa_a\">\r\n<div class=\"sofa_pic\"><img class=\"alignleft\" title=\"До\" src=\"https://kraftman.ru/1.jpg\" alt=\"Диван (состояния ДО)\" width=\"46%\" /><img class=\"alignleft\" title=\"После\" src=\"https://kraftman.ru/2.jpg\" alt=\"Диван (состояния ПОСЛЕ)\" width=\"46%\" /></div>\r\n<div class=\"sofa_text\">\r\n<div class=\"desc\">\r\n<div class=\"desc_text\">Типичная «неожиданность» — авторское крепление отдельных элементов конструкции. Слева — фото дивана «Честер» до и после перетяжки. Модель с двумя подушками для сидения и каретной стяжкой белой кожи на спинках. В торце подлокотников — фигурные зеркала. Чтобы добраться до крепежа накладок, зеркальные вставки пришлось разбить, вырезать такие же в мастерской. Это повлекло дополнительные временные издержки и отразилось на цене.</div>\r\n</div>\r\n<div class=\"sofa_price\">Цена: 7 000р</div>\r\n</div>\r\n</div>\r\n<div class=\"sofa_b\">\r\n<div class=\"sofa_pic\"><img class=\"alignleft\" title=\"До\" src=\"https://kraftman.ru/3.jpg\" alt=\"Диван (состояния ДО)\" width=\"46%\" /><img class=\"alignleft\" title=\"После\" src=\"https://kraftman.ru/4.jpg\" alt=\"Диван (состояния ПОСЛЕ)\" width=\"46%\" /></div>\r\n<div class=\"sofa_text\">\r\n<div class=\"desc\">\r\n<div class=\"desc_text\">\r\n\r\nИзучив ассортимент обивочных материалов, хозяева дивана остановились на темно-красной коже (для основания, подлокотников, спинки) и на бежевом тканевом материале (для четырех подушек). В цену за ремонт, кроме стоимости материалов, вошли машинная прострочка и формировка элементов декора.\r\n\r\n</div>\r\n</div>\r\n<div class=\"sofa_price\">Цена: 1 000р</div>\r\n</div>\r\n</div>\r\n</div>\r\n<table class=\"sofa_table\">\r\n<tbody>\r\n<tr>\r\n<td>Материал</td>\r\n<td>Цена, р</td>\r\n</tr>\r\n<tr>\r\n<td>Велюр</td>\r\n<td>от 500</td>\r\n</tr>\r\n<tr>\r\n<td>Искусственная кожа</td>\r\n<td>от 7 000</td>\r\n</tr>\r\n<tr>\r\n<td>Велюр</td>\r\n<td>от 500</td>\r\n</tr>\r\n<tr>\r\n<td>Искусственная кожа</td>\r\n<td>от 7 000</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div class=\"uCalc_45087\"></div>\r\n<script> var widgetOptions45087 = { bg_color: \"transparent\" }; (function() { var a = document.createElement(\"script\"); a.async = true; a.src = (document.location.protocol == \"https:\" ? \"https:\" : \"http:\") + \"//ucalc.pro/api/widget.js?id=45087&t=\"+Math.floor(new Date()/1800000); document.getElementsByTagName(\"head\")[0].appendChild(a) })();</script>\r\n\r\nКак видно из иллюстрированных примеров, ответ на закономерный вопрос «сколько стоит перетянуть мебель по-новому?» зависит от ряда моментов. На цену влияют: характер повреждений, трудоемкость изготовления новых деталей для замены пришедших в негодность старых и т. п. В отдельных случаях <a href=\"https://kraftman.ru/tseny/\">цена</a> обивки дивана способна достичь трети от стоимости нового изделия. Рассмотрим, от чего же зависят расценки и как можно сэкономить на перетяжке мягкой мебели, которая обитая прохудившимся материалом.\r\n<h2>Сколько стоит перетянуть мебель для сидения и отдыха</h2>\r\nНа этот вопрос однозначного ответа не дать: слишком много факторов влияет на формирование суммы, предъявляемой к оплате. Перечислим главные:\r\n<ul>\r\n 	<li>Стоимость обивочной ткани — если остов перетягивается дорогим материалом, потребуется больше внимательности, времени, в итоге и сама смена обивки обойдется дороже;</li>\r\n 	<li>Качество наполнителей — обладающие повышенными эксплуатационными характеристиками не могут стоить дешево;</li>\r\n 	<li>Конструкция — перетяжка «прямых» диванов экономичнее близкого по параметрам мягкого уголка;</li>\r\n 	<li>Декоративная отделка, инкрустация.</li>\r\n</ul>\r\nРазумный учет перечисленного позволит рачительно расходовать средства. В результате, кажущаяся очень дорогой презентабельная обивка дивана недорого обойдется для бюджета семьи, компании, предприятия.\r\n\r\nПонадобилась перетяжка диванов? Самой Судьбе было угодно направить вас к лучшим мастерам Москвы и Московской области! Не упускайте шанс — заказывайте услуги у профессионалов! Де-факто по цене перетяжки вы получите новый диван. Спектр предоставляемых нами услуг этим не ограничен. В «Крафтман» заказывают <a href=\"http://kraftman.ru/portfolio/obivka-kresel/\">обивку кресел</a>, стульев, пр.\r\n\r\nОбращайтесь! Звоните по телефону +7(495)506-01-24! Мы подарим вашей мебели вторую жизнь!\r\n<div class=\"iphorm-elements iphorm-elements-5 iphorm-clearfix\">\r\n<div class=\"iphorm-group-wrap iphorm_5_4-group-wrap iphorm-clearfix iphorm-labels-inside iphorm-group-style-plain iphorm-group-alignment-left\" style=\"float: left;\">\r\n<div class=\"iphorm-group-elements\">\r\n<div class=\"iphorm-group-row iphorm-clearfix iphorm-group-row-3cols\">\r\n<div class=\"iphorm-element-wrap iphorm-element-wrap-text iphorm_5_1-element-wrap iphorm-clearfix iphorm-labels-inside iphorm-element-required\">\r\n<div class=\"iphorm-element-spacer iphorm-element-spacer-text iphorm_5_1-element-spacer\">\r\n\r\n<label class=\"iphorm_5_1-outer-label\" for=\"iphorm_5_1_5aa0f0ce862d7\">ИМЯ<span class=\"iphorm-required\">*</span></label>\r\n<div class=\"iphorm-input-wrap iphorm-input-wrap-text iphorm_5_1-input-wrap\"><input id=\"iphorm_5_1_5aa0f0ce862d7\" class=\"iphorm-element-text iphorm_5_1\" name=\"iphorm_5_1\" type=\"text\" value=\"\" /></div>\r\n<div class=\"iphorm-errors-wrap iphorm-hidden\"></div>\r\n</div>\r\n</div>\r\n<div class=\"iphorm-element-wrap iphorm-element-wrap-text iphorm_5_2-element-wrap iphorm-clearfix iphorm-labels-inside iphorm-element-required\">\r\n<div class=\"iphorm-element-spacer iphorm-element-spacer-text iphorm_5_2-element-spacer\">\r\n\r\n<label class=\"iphorm_5_2-outer-label\" for=\"iphorm_5_2_5aa0f0ce862d7\">ТЕЛЕФОН<span class=\"iphorm-required\">*</span></label>\r\n<div class=\"iphorm-input-wrap iphorm-input-wrap-text iphorm_5_2-input-wrap\"><input id=\"iphorm_5_2_5aa0f0ce862d7\" class=\"iphorm-element-text iphorm_5_2\" name=\"iphorm_5_2\" type=\"text\" value=\"\" /></div>\r\n<div class=\"iphorm-errors-wrap iphorm-hidden\"></div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"iphorm-submit-wrap iphorm-submit-wrap-5 iphorm-clearfix\" style=\"float: left; margin-top: 0; margin-bottom: 0; margin-left: 15px; border-radius: 5px;\">\r\n<div class=\"iphorm-submit-input-wrap iphorm-submit-input-wrap-5\"><button class=\"iphorm-submit-element\" name=\"iphorm_submit\" type=\"submit\"><span style=\"height: 40px; line-height: 40px; border-radius: 5px;\"><em style=\"height: 40px; line-height: 40px; border-radius: 5px;\">ЗАЯВКА</em></span></button></div>\r\n<div class=\"iphorm-loading-wrap\"><span class=\"iphorm-loading\">Пожалуйста подождите</span></div>\r\n</div>\r\n</div>\r\n[/vc_column_text][/vc_column][/vc_row]', 'Перетяжка дивана', '', 'inherit', 'closed', 'closed', '', '1854-revision-v1', '', '', '2018-03-21 12:11:24', '2018-03-21 09:11:24', '', 1854, 'https://kraftman.ru/1854-revision-v1/', 0, 'revision', '', 0),
(2106, 1, '2018-03-21 12:19:26', '2018-03-21 09:19:26', '<div class=\"inner\">\r\n\r\n<span style=\"font-size: 24px;\">Миссия</span>\r\n\r\nМы не ремонтируем и не восстанавливаем мебель, мы выполняем авторскую работу на основе уже имеющегося предмета мебелировки, лаконично интегрируя его в общую концепцию дизайна интерьера.\r\n\r\n<span style=\"font-size: 24px;\">О компании</span>\r\n\r\nУже более 30 лет обслуживание предметов интерьера является основным делом нашей семьи.\r\nНа разных этапах развития предприятие менялось: на одном это была маленькая мастерская в подмосковной Тарасовке, со швейной машинкой и обивочным столом. На другом – целое мебельное производство ООО \"Тайнинка\" со своей пилорамой и магазинами на северо-востоке Москвы.\r\nК началу столетия компания прочно заняла свою нишу в сфере перетяжки и реставрации мебели, обслуживая не только частных клиентов, но и такие организации как отель \"Метрополь\", \"Балчуг Кемпински\", сеть ресторанов \"Мак Дональдс\".\r\nВ 2007 году, подчиняясь тенденциям рынка, на свет появился бренд \"Мебельная мастерская Крафтман\". Новое название символизирует собой надёжность и качество предоставляемого сервиса.\r\nОрганизация, возглавляемая уже вторым поколением семьи, продолжает свой путь и приумножает опыт. Сегодня мы расширяем географию и рады предоставить наш сервис не только в Москве и области, но также в Сочи и Санкт-Петербурге.\r\nЕсли Ваша любимая мебель не вписывается в новый интерьер, просто обратитесь в Крафтман, и Вы гарантированно получите качественный сервис и превосходный результат.\r\n\r\nИП Владислав Чибисов\r\n\r\n</div>', 'Традиции с 1986 года', '', 'publish', 'closed', 'closed', '', 'traditsii-s-1986-goda', '', '', '2018-04-01 18:33:54', '2018-04-01 15:33:54', '', 0, 'https://kraftman.ru/?page_id=2106', 0, 'page', '', 0),
