(2125, 1, '2018-03-22 12:03:45', '2018-03-22 09:03:45', '[vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" css=\".vc_custom_1475946467474{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Мебельная мастерская КРАФТМАН\" font_container=\"tag:h1|font_size:20px|text_align:left|line_height:20px\" css=\".vc_custom_1521708960672{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<h3>Всегда к Вашим услугам:</h3>\r\n<h1>Перетяжка мебели в Москве</h1>\r\nДаже у самой качественной мебели есть свой срок. Когда необходимо обновить устаревшую, но любимую мебель, требуется ремонт, реставрация или перетяжка мебели.\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/1.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/2.jpg\" /></div>\r\n<h2>О компании</h2>\r\nМебельная мастерская Крафтман- лидер рынка, специалисты которой готовы выполнять работы любой сложности и в любом объеме, чтобы подарить вашим вещам новую жизнь.\r\n\r\nКомпания предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и заставит старую мебель выглядеть дорого и изысканно.[/vc_column_text][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_respo