tem][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row][vc_row height=\"auto\" el_id=\"brand\"][vc_column][vc_custom_heading text=\"ОТЗЫВЫ\" font_container=\"tag:h6|font_size:14px|text_align:left|line_height:14px\" google_fonts=\"font_family:Roboto%20Condensed%3A300%2C300italic%2Cregular%2Citalic%2C700%2C700italic|font_style:300%20light%20regular%3A300%3Anormal\" css=\".vc_custom_1520339921763{margin-bottom: 2px !important;}\"][us_logos columns=\"5\" with_indents=\"1\" orderby=\"rand\" arrows=\"1\" auto_scroll=\"1\" interval=\"3\" items=\"%5B%7B%22image%22%3A%22440%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fharry-winston-mercury-ralph-laurent%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22438%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Flukojl%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22441%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fhotel-metropol-moscow%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22433%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Famerikanskaya-torgovaya-palata%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22435%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Ffski%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22434%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fotel-borodino%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22439%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fmcdonalds%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22443%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fthe-ritz-carlton%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22442%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fradiostantsiya-serebryanyj-dozhd%7C%7C%7C%22%7D%2C%7B%22image%22%3A%22444%22%2C%22link%22%3A%22url%3A%252Fdlya-organizatsij%252Fhotel-savoy-moscow%7C%7C%7C%22%7D%5D\"][us_separator type=\"invisible\"][/vc_column][/vc_row][vc_row height=\"auto\" width=\"full\" css=\".vc_custom_1520334013097{margin-top: -20px !important;}\"][vc_column width=\"3/3\" css=\".vc_custom_1476217390778{padding-top: 0px !important;}\"][us_btn text=\"Оставить отзыв\" link=\"url:%23leave_feedback_form|title:%D0%9E%D1%81%D1%82%D0%B0%D0%B2%D0%B8%D1%82%D1%8C%20%D0%BE%D1%82%D0%B7%D1%8B%D0%B2||\" align=\"center\" el_class=\"fancybox\"][vc_column_text]\r\n<p style=\"text-align: left;\">[iphorm id=\"5\" name=\"ЗАПРОС\"]</p>\r\n\r\n<h2>Вдохните в любимую мебель с историей новую жизнь</h2>\r\nКогда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели.\r\n\r\nНа этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.\r\nКрафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу.\r\nСпециалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.\r\n<h2>Этапы работы</h2>\r\n<h3>Выезд дизайнера</h3>\r\nПредставитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.\r\n<h3>Согласование обивочного материала</h3>\r\nЕсли вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.\r\n<h3>Согласование дат транспортировки</h3>\r\nПосле того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.\r\n<h3>Возврат перетянутой мебели</h3>\r\nСпустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.\r\n<h2>Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][vc_column_text]Мы с радостью ответим на все ваши вопросы![/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_video link=\"https://www.youtube.com/watch?v=y02XGHuJPn8&amp;feature=youtu.be\" max_width=\"500\" align=\"center\"][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-03-26 23:28:46', '2018-03-26 20:28:46', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0);
