10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row height=\"auto\" width=\"full\" css=\".vc_custom_1520334013097{margin-top: -20px !important;}\"][vc_column width=\"3/3\" css=\".vc_custom_1476217390778{padding-top: 0px !important;}\"][vc_column_text]\r\n<h2>Этапы работы</h2>\r\n<ul>\r\n 	<li>Выезд дизайнера\r\nПредставитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</li>\r\n 	<li>Согласование обивочного материала\r\nЕсли вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</li>\r\n 	<li>Согласование дат транспортировки\r\nПосле того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</li>\r\n 	<li>Возврат перетянутой мебели\r\nСпустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</li>\r\n</ul>\r\n<h2 style=\"text-align: center;\">Благодарственные письма от ведущих компаний</h2>\r\n[/vc_column_text][vc_column_text][feedback][/vc_column_text][us_btn text=\"Оставить отзыв\" link=\"url:%23leave_feedback_form|title:%D0%9E%D1%81%D1%82%D0%B0%D0%B2%D0%B8%D1%82%D1%8C%20%D0%BE%D1%82%D0%B7%D1%8B%D0%B2||\" align=\"center\" el_class=\"fancybox\"][vc_column_text]\r\n<h2>Вдохните в любимую мебель с историей новую жизнь</h2>\r\n<p style=\"text-indent: 50px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 50px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][vc_column_text]Мы с радостью ответим на все ваши вопросы![/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]<iframe src=\"https://www.youtube.com/embed/y02XGHuJPn8?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2>Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n\r\n[/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-03-29 11:43:56', '2018-03-29 08:43:56', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(2270, 1, '2018-03-29 12:20:37', '2018-03-29 09:20:37', '[vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" css=\".vc_custom_1475946467474{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:20px|text_align:left|line_height:20px\" css=\".vc_custom_1521838277380{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 50px;\">Даже у самой качественной мебели есть свой срок. Когда необходимо обновить устаревшую, но любимую мебель, требуется ремонт, реставрация или перетяжка мебели.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n<div style=\"background-color: #d5d5d5;\">\r\n<p style=\"text-indent: 50px;\">Мебельная мастерская Крафтман- лидер рынка, специалисты которой готовы выполнить работы любой сложности и в любом объеме, чтобы подарить вашей мебели новую жизнь. Компания предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит вашу мебель в дорогой предмет интерьера.</p>\r\n\r\n</div>\r\n[/vc_column_text][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscap