(2407, 1, '2018-04-03 16:42:58', '2018-04-03 13:42:58', '[vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" css=\".vc_custom_1475946467474{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:10px\" css=\".vc_custom_1522357143497{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Даже у самой качественной мебели есть свой срок. Когда необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели.</p>\r\n<p style=\"text-indent: 25px;\">Специалисты мебельной мастерской «Крафтман» готовы выполнить работы любой сложности и подарить вашей мебели новую жизнь. Компания предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n<p style=\"text-indent: 25px;\">[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]</p>\r\n\r\n<h2 style=\"text-align: center;\">Вызовите дизайнера</h2>\r\n<p style=\"text-align: center;\">Наш специалист приедет к вам с каталогами образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2385\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Согласуйте обивочный материал</h2>\r\n<p style=\"text-align: center;\">Мы поможем подобрать и скомбинировать ткани, а если нужно – придумать новые элементы декора: канты, ранты, пиковку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Согласуйте даты транспортировки</h2>\r\n<p style=\"text-align: center;\">Мы вывозим предмет мебели в свою мастерскую. Над каждым изделием трудится бригада мастеров: здесь снимут старый чехол, разработают лекала для нового, сошьют его и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Наслаждайтесь результатом</h2>\r\n<p style=\"text-align: center;\">Через 2 недели мы доставим ваши диван, кресло, гарнитур в обновленном виде. Если необходимо ускорить процесс, мы выполним срочный заказ на отдельных условиях.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row el_class=\".calc-frame\"][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row height=\"auto\" width=\"full\" css=\".vc_custom_1520334013097{margin-top: -20px !important;}\"][vc_column width=\"3/3\" css=\".vc_custom_1476217390778{padding-top: 0px !important;}\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работы</h2>\r\n<ul>\r\n 	<li>Выезд дизайнера\r\nПредставитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</li>\r\n 	<li>Согласование обивочного материала\r\nЕсли вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</li>\r\n 	<li>Согласование дат транспортировки\r\nПосле того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</li>\r\n 	<li>Возврат перетянутой мебели\r\nСпустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</li>\r\n</ul>\r\n[/vc_column_text][vc_column_text]\r\n<div style=\"clear: both;\">\r\n<h2 style=\"text-align: center;\">Вдохните в любимую мебель новую жизнь</h2>\r\n</div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Благодарственные письма от ведущих компаний</h2>\r\n[/vc_column_text][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-04-03 16:42:58', '2018-04-03 13:42:58', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
(2408, 0, '2018-04-03 17:58:38', '0000-00-00 00:00:00', 'Добрый день  Кузьма Милютин \r\nГлянь сайтик с него \r\nвыписала себе большие \r\nсредства  только не кому не говори \r\n \r\nhttp://bit.ly/2GrFPVN', 'Наталья Мышкина', '', 'pending', 'closed', 'closed', '', '', '', '', '2018-04-03 17:58:38', '0000-00-00 00:00:00', '', 0, 'https://kraftman.ru/?p=2408', 0, 'feedback_new', '', 0),
(2409, 1, '2018-04-03 18:07:50', '2018-04-03 15:07:50', '[vc_row][vc_column][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Стулья относятся к числу самой часто используемой мебели, поэтому максимально подвержены износу. Когда обивка сидения потеряла привлекательный внешний вид, а сам корпус остался в хорошем состоянии, отличным решением может стать перетяжка стульев.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/5.PNG\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/6.PNG\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2>Крафтман - для тех, кто выбирает качество</h2>\r\n<p style=\"text-indent: 25px;\">Мебельная мастерская Крафтман - компания, которая несколько десятилетий занимается ремонтом и перетяжкой стульев в Москве, недорого предлагая услуги высокого качества. Над преображением мебели работает команда профессиональных мастеров, которые используют материалы от мировых производителей и выполняют работу на высококлассном оборудовании. Все это позволяет компании Крафман гарантировать высокий результат и перетянуть стулья для по выгодной стоимости.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"2/3\"][vc_row_inner][vc_column_inner width=\"1/2\"][vc_column_text]Было[/vc_column_text][us_single_image image=\"2162\" size=\"medium\" lightbox=\"1\"][/vc_column_inner][vc_column_inner width=\"1/2\"][vc_column_text]Стало[/vc_column_text][us_single_image image=\"2163\" size=\"medium\" lightbox=\"1\"][us_single_image image=\"219\" size=\"medium\" lightbox=\"1\"][/vc_column_inner][/vc_row_inner][/vc_column][vc_column width=\"1/3\"][vc_column_text]\r\n<h2>Что включают в себя работы</h2>\r\n<p style=\"text-indent: 25px;\">Стандартный набор услуг, характерный как для перетяжки кухонных стульев, так и для других их видов, состоит из частичной реставрации предметов: удаление с поверхности грязи и царапин. Также производится замена ткани, наполнителя и отделка тесьмой. Предварительно к вам приезжает представитель компании и показывает образцы материалов, подробно консультируя о необходимых работах.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2>Эффективное решение главных проблем</h2>\r\n<p style=\"text-indent: 25px;\">Перетяжка стульев в Москве может потребоваться, когда обладатель хорошей и дорогой мебели заметил ее естественный износ: обивка устарела или на корпусе появились царапины. Когда могут потребоваться специалисты для перетяжки сидений стульев?</p>\r\n\r\n<ul>\r\n 	<li>Когда речь идет о старинной мебели, важна деликатность и точность. Сложно выполнить перетяжку стульев самостоятельно, не повредив декоративную отделку, цена ошибки тут крайне высока. Качественная перетяжка стула позволяет не только обновить обивку, но и сохранить индивидуальность мягкой мебели.</li>\r\n 	<li>Выбор ткани - не такая простая задача, как может показаться на первый взгляд. Производители предлагают широкий выбор материалов разных видов. Специалист помогает клиенту сориентироваться, какую ткань лучше покупать, если нужна перетяжка барных стульев, и требуется ли в конкретном случае обивка стульев кожей.</li>\r\n 	<li>Профессионал сможет точно определить, когда необходима замена не только обивки, но и наполнителя. Это позволит сразу понять, сколько стоит весь перечень работ, а также выполнить их на должном уровне.</li>\r\n</ul>\r\n<p style=\"text-indent: 25px;\">Решением всех проблем перетяжки мебели станет обращение в мастерскую “Крафтман”, вы можете не сомневаться, что стулья прослужат вам еще очень долго.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2>Благодарственные письма от ведущих компаний</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h3>Преимущества компании Крафтман</h3>\r\n<ul>\r\n 	<li>Сотрудники компании реализуют индивидуальный подход к клиенту, учитывая потребности каждого. Они способны идеально повторить любой шов и реализовать самые сложные идеи.</li>\r\n 	<li>Каждый проект мебельной мастерской - это авторская работа квалифицированных мастеров с огромным опытом. “Крафтман” превращает старые вещи в настоящее произведение искусства.</li>\r\n 	<li>Мастерская обладает всеми техническими возможностями для качественной работы.</li>\r\n 	<li>Гарантия три года.</li>\r\n</ul>\r\n<p style=\"text-indent: 25px;\">Оставляйте заявки у наших менеджеров, чтобы подарить Вашей мебели новую жизнь!</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][/vc_row]', 'Перетяжка стульев', '', 'inherit', 'closed', 'closed', '', '2161-revision-v1', '', '', '2018-04-03 18:07:50', '2018-04-03 15:07:50', '', 2161, 'https://kraftman.ru/2161-revision-v1/', 0, 'revision', '', 0),
(2410, 1, '2018-04-03 18:21:44', '2018-04-03 15:21:44', '[vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" css=\".vc_custom_1475946467474{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:10px\" css=\".vc_custom_1522357143497{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Даже у самой качественной мебели есть свой срок. Когда необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели.</p>\r\n<p style=\"text-indent: 25px;\">Специалисты мебельной мастерской «Крафтман» готовы выполнить работы любой сложности и подарить вашей мебели новую жизнь. Компания предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n<p style=\"text-indent: 25px;\">[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]</p>\r\n\r\n<h2 style=\"text-align: center;\">Вызовите дизайнера</h2>\r\n<p style=\"text-align: center;\">Наш специалист приедет к вам с каталогами образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2385\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Согласуйте обивочный материал</h2>\r\n<p style=\"text-align: center;\">Мы поможем подобрать и скомбинировать ткани, а если нужно – придумать новые элементы декора: канты, ранты, пиковку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Согласуйте даты транспортировки</h2>\r\n<p style=\"text-align: center;\">Мы вывозим предмет мебели в свою мастерскую. Над каждым изделием трудится бригада мастеров: здесь снимут старый чехол, разработают лекала для нового, сошьют его и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Наслаждайтесь результатом</h2>\r\n<p style=\"text-align: center;\">Через 2 недели мы доставим ваши диван, кресло, гарнитур в обновленном виде. Если необходимо ускорить процесс, мы выполним срочный заказ на отдельных условиях.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работ</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row el_class=\".calc-frame\"][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row height=\"auto\" width=\"full\" css=\".vc_custom_1520334013097{margin-top: -20px !important;}\"][vc_column width=\"3/3\" css=\".vc_custom_1476217390778{padding-top: 0px !important;}\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работы</h2>\r\n<ul>\r\n 	<li>Выезд дизайнера\r\nПредставитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</li>\r\n 	<li>Согласование обивочного материала\r\nЕсли вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</li>\r\n 	<li>Согласование дат транспортировки\r\nПосле того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</li>\r\n 	<li>Возврат перетянутой мебели\r\nСпустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</li>\r\n</ul>\r\n[/vc_column_text][vc_column_text]\r\n<div style=\"clear: both;\">\r\n<h2 style=\"text-align: center;\">Вдохните в любимую мебель новую жизнь</h2>\r\n</div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Благодарственные письма от ведущих компаний</h2>\r\n[/vc_column_text][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-04-03 18:21:44', '2018-04-03 15:21:44', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(2411, 1, '2018-04-03 18:22:11', '2018-04-03 15:22:11', '[vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" css=\".vc_custom_1475946467474{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:10px\" css=\".vc_custom_1522357143497{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Даже у самой качественной мебели есть свой срок. Когда необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели.</p>\r\n<p style=\"text-indent: 25px;\">Специалисты мебельной мастерской «Крафтман» готовы выполнить работы любой сложности и подарить вашей мебели новую жизнь. Компания предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n<p style=\"text-indent: 25px;\">[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]</p>\r\n\r\n<h2 style=\"text-align: center;\">Этапы работ</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Вызовите дизайнера</h2>\r\n<p style=\"text-align: center;\">Наш специалист приедет к вам с каталогами образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2385\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Согласуйте обивочный материал</h2>\r\n<p style=\"text-align: center;\">Мы поможем подобрать и скомбинировать ткани, а если нужно – придумать новые элементы декора: канты, ранты, пиковку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Согласуйте даты транспортировки</h2>\r\n<p style=\"text-align: center;\">Мы вывозим предмет мебели в свою мастерскую. Над каждым изделием трудится бригада мастеров: здесь снимут старый чехол, разработают лекала для нового, сошьют его и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Наслаждайтесь результатом</h2>\r\n<p style=\"text-align: center;\">Через 2 недели мы доставим ваши диван, кресло, гарнитур в обновленном виде. Если необходимо ускорить процесс, мы выполним срочный заказ на отдельных условиях.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row el_class=\".calc-frame\"][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/u