(2606, 1, '2018-04-23 22:56:17', '2018-04-23 19:56:17', '[vc_row][vc_column][vc_column_text]\r\n<p style=\"font-size: 24px; text-indent: 25px; line-height: 1.5;\">Среди предложенных нами каталогов вы найдете образцы передовых высокотехнологичных материалов для обивки домашней и уличной мебели, обладающих не только великолепным внешним видом и приятными тактильными свойствами, но и другими не менее важными показателями.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2>Цены на материалы</h2>\r\n<b>Цены на все материалы совпадают с ценами на сайтах поставщиков</b>\r\n<a style=\"color: blue;\" href=\"https://kraftman.ru/wp-content/uploads/2016/07/EXTERIO-tseny.docx\">Скачать прайс на материалы EXTERIO</a>\r\n<a style=\"color: blue;\" href=\"https://kraftman.ru/wp-content/uploads/2016/07/Ametist-tseny.docx\">Скачать прайс на материалы Аметист</a>\r\n<a style=\"color: blue;\" href=\"https://kraftman.ru/wp-content/uploads/2016/07/Mebeleri-tseny.docx\">Скачать прайс на материалы Мебельери</a>\r\n<a style=\"color: blue;\" href=\"https://kraftman.ru/wp-content/uploads/2016/07/Soyuz-M-tseny.docx\">Скачать прайс на материалы Союз М</a>[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text][/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ultimate_carousel slider_type=\"full_width\" slide_to_scroll=\"single\" autoplay_speed=\"1300\" adaptive_height=\"on\"][interactive_banner_2 banner_title=\"Перетяжка мягкой мебели\" banner_desc=\"Подробнее о перетяжке мягкой мебели ...\" heading_tag=\"h3\" banner_image=\"id^223|url^http://kraftman.ru/wp-content/uploads/2016/02/peretyajka-myakgoj-combine1-s.jpg|caption^null|alt^null|title^peretyajka-myakgoj-combine1-s|description^null\" banner_link=\"url:http%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|title:%D1%80%D0%B5%D0%BC%D0%BE%D0%BD%D1%82%20%D0%BC%D0%B5%D0%B1%D0%B5%