0/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-07-25 18:28:58', '2018-07-25 15:28:58', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
(3385, 1, '2018-07-25 18:32:38', '2018-07-25 15:32:38', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3372|url^https://kraftman.ru/wp-content/uploads/2018/07/craftman2.jpg|caption^null|alt^null|title^craftman2|description^null\" bg_image_repeat=\"no-repeat\" bg_override=\"full\" css=\".vc_custom_1532531207118{margin: 0px !important;border-width: 0px !important;padding: 0px !important;}\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" disable_element=\"yes\" css=\".vc_custom_1532531080101{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:35px\" css=\".vc_custom_1523182718086{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Компания Крафтман предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Если необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532531699409{margin-top: 50px !important;}\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работ</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532532360573{padding-right: 15px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Выезд\r\nдизайнера</h2>\r\n<p style=\"text-align: center;\">Представитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование обивочных материалов</h2>\r\n<p style=\"text-align: center;\">Если вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование дат транспортировки</h2>\r\n<p style=\"text-align: center;\">После того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Возврат перетянутой мебели</h2>\r\n<p style=\"text-align: center;\">Спустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-07-25 18:32:38', '2018-07-25 15:32:38', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
(3386, 1, '2018-07-25 18:35:53', '2018-07-25 15:35:53', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3372|url^https://kraftman.ru/wp-content/uploads/2018/07/craftman2.jpg|caption^null|alt^null|title^craftman2|description^null\" bg_image_repeat=\"no-repeat\" bg_override=\"full\" css=\".vc_custom_1532531207118{margin: 0px !important;border-width: 0px !important;padding: 0px !important;}\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" disable_element=\"yes\" css=\".vc_custom_1532531080101{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:35px\" css=\".vc_custom_1523182718086{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Компания Крафтман предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Если необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532531699409{margin-top: 50px !important;}\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работ</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532532360573{padding-right: 15px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Выезд\r\nдизайнера</h2>\r\n<p style=\"text-align: center;\">Представитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование обивочных материалов</h2>\r\n<p style=\"text-align: center;\">Если вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование дат транспортировки</h2>\r\n<p style=\"text-align: center;\">После того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Возврат перетянутой мебели</h2>\r\n<p style=\"text-align: center;\">Спустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-07-25 18:35:53', '2018-07-25 15:35:53', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3387, 1, '2018-07-25 18:42:31', '2018-07-25 15:42:31', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3372|url^https://kraftman.ru/wp-content/uploads/2018/07/craftman2.jpg|caption^null|alt^null|title^craftman2|description^null\" bg_image_repeat=\"no-repeat\" bg_override=\"full\" css=\".vc_custom_1532531207118{margin: 0px !important;border-width: 0px !important;padding: 0px !important;}\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" disable_element=\"yes\" css=\".vc_custom_1532531080101{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:35px\" css=\".vc_custom_1523182718086{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Компания Крафтман предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Если необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532533260422{margin-top: 50px !important;}\" el_id=\"etap\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работ</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532532360573{padding-right: 15px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Выезд\r\nдизайнера</h2>\r\n<p style=\"text-align: center;\">Представитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование обивочных материалов</h2>\r\n<p style=\"text-align: center;\">Если вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование дат транспортировки</h2>\r\n<p style=\"text-align: center;\">После того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Возврат перетянутой мебели</h2>\r\n<p style=\"text-align: center;\">Спустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-07-25 18:42:31', '2018-07-25 15:42:31', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
(3388, 1, '2018-07-25 19:01:39', '2018-07-25 16:01:39', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3372|url^https://kraftman.ru/wp-content/uploads/2018/07/craftman2.jpg|caption^null|alt^null|title^craftman2|description^null\" bg_image_repeat=\"no-repeat\" bg_override=\"full\" css=\".vc_custom_1532531207118{margin: 0px !important;border-width: 0px !important;padding: 0px !important;}\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" disable_element=\"yes\" css=\".vc_custom_1532531080101{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:35px\" css=\".vc_custom_1523182718086{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Компания Крафтман предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Если необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532533260422{margin-top: 50px !important;}\" el_id=\"etap\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работ</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532532360573{padding-right: 15px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Выезд\r\nдизайнера</h2>\r\n<p style=\"text-align: center;\">Представитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование обивочных материалов</h2>\r\n<p style=\"text-align: center;\">Если вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование дат транспортировки</h2>\r\n<p style=\"text-align: center;\">После того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Возврат перетянутой мебели</h2>\r\n<p style=\"text-align: center;\">Спустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]PHA+SSBhbSByYXcgaHRtbCBibG9jay48YnIvPkNsaWNrIGVkaXQgYnV0dG9uIHRvIGNoYW5nZSB0aGlzIGh0bWw8L3A+[/vc_raw_html][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-07-25 19:01:39', '2018-07-25 16:01:39', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
(3389, 1, '2018-07-25 19:02:12', '2018-07-25 16:02:12', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3372|url^https://kraftman.ru/wp-content/uploads/2018/07/craftman2.jpg|caption^null|alt^null|title^craftman2|description^null\" bg_image_repeat=\"no-repeat\" bg_override=\"full\" css=\".vc_custom_1532531207118{margin: 0px !important;border-width: 0px !important;padding: 0px !important;}\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" css=\".vc_custom_1532534530249{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:35px\" css=\".vc_custom_1523182718086{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Компания Крафтман предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Если необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532533260422{margin-top: 50px !important;}\" el_id=\"etap\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работ</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532532360573{padding-right: 15px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Выезд\r\nдизайнера</h2>\r\n<p style=\"text-align: center;\">Представитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование обивочных материалов</h2>\r\n<p style=\"text-align: center;\">Если вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование дат транспортировки</h2>\r\n<p style=\"text-align: center;\">После того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Возврат перетянутой мебели</h2>\r\n<p style=\"text-align: center;\">Спустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html]PHA+SSBhbSByYXcgaHRtbCBibG9jay48YnIvPkNsaWNrIGVkaXQgYnV0dG9uIHRvIGNoYW5nZSB0aGlzIGh0bWw8L3A+[/vc_raw_html][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-07-25 19:02:12', '2018-07-25 16:02:12', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3390, 1, '2018-07-25 19:03:18', '2018-07-25 16:03:18', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3372|url^https://kraftman.ru/wp-content/uploads/2018/07/craftman2.jpg|caption^null|alt^null|title^craftman2|description^null\" bg_image_repeat=\"no-repeat\" bg_override=\"full\" css=\".vc_custom_1532531207118{margin: 0px !important;border-width: 0px !important;padding: 0px !important;}\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html][/vc_raw_html][/vc_column][/vc_row][vc_row content_placement=\"top\" columns_type=\"none\" height=\"auto\" width=\"full\" css=\".vc_custom_1532534530249{border-right-width: 0px !important;border-left-width: 0px !important;padding-right: 0px !important;padding-left: 0px !important;}\"][vc_column css=\".vc_custom_1521708971234{padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_custom_heading text=\"Перетяжка мебели в Москве\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:35px\" css=\".vc_custom_1523182718086{padding-top: 0px !important;padding-left: 0px !important;}\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Компания Крафтман предоставляет качественные услуги и первоклассный сервис по сравнительно недорогой стоимости. Если необходимо обновить устаревшие, но любимые предметы интерьера, требуется ремонт, реставрация или перетяжка мебели. Вы можете рассчитывать на то, что мастер учтет все ваши пожелания при замене обивки и превратит старую мебель в дорогой предмет интерьера.</p>\r\n\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/22.jpg\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/66.jpg\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532533260422{margin-top: 50px !important;}\" el_id=\"etap\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Этапы работ</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532532360573{padding-right: 15px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Выезд\r\nдизайнера</h2>\r\n<p style=\"text-align: center;\">Представитель компании подъезжает в удобное для вас время, подробно консультирует по всем вопросам и показывает каталоги образцов.</p>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование обивочных материалов</h2>\r\n<p style=\"text-align: center;\">Если вы сомневаетесь в выборе тканей или хотите добавить новые элементы декора, специалисты предложат вам наиболее подходящие материалы и их грамотное сочетание.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Согласование дат транспортировки</h2>\r\n<p style=\"text-align: center;\">После того, как все детали оговорены, ваша мебель перевозится в частную мастерскую, где над ней будет работать команда профессионалов. Они снимут старый чехол, сделают новые лекала, сошьют по ним обивку и выполнят перетяжку.</p>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Возврат перетянутой мебели</h2>\r\n<p style=\"text-align: center;\">Спустя две недели мы привозим мебель обратно в ее новом виде. Наша компания готова ускорить сроки, если в этом есть необходимость. Теперь вы можете наслаждаться полученным результатом.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][ult_ihover thumb_shape=\"square\" thumb_height_width=\"245\" responsive_size=\"on\" res_thumb_height_width=\"150\" gutter_width=\"4\" el_class=\"style=``padding: 4px;``\"][ult_ihover_item title=\"ОБИВКА ДИВАНА\" thumb_img=\"id^1660|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_divanov_s.png|caption^null|alt^ОБИВКА ДИВАНОВ|title^ОБИВКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КРЕСЕЛ\" thumb_img=\"id^1661|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_kreslel_s.png|caption^null|alt^ОБИВКА КРЕСЕЛ|title^ОБИВКА КРЕСЕЛ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-kresel%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-07-25 19:03:18', '2018-07-25 16:03:18', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
