:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЕБЕЛИ\" thumb_img=\"id^1662|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_mebeli_s.png|caption^null|alt^ОБИВКА МЕБЕЛИ|title^ОБИВКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1663|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_myagkoj_mebeli_s.png|caption^null|alt^ОБИВКА МЯГКОЙ МЕБЕЛИ|title^ОБИВКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ОБИВКА СТУЛЬЕВ\" thumb_img=\"id^1664|url^https://kraftman.ru/wp-content/uploads/2016/10/obivka_stulev_s.png|caption^null|alt^ОБИВКА СТУЛЬЕВ|title^ОБИВКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fobivka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА ДИВАНА\" thumb_img=\"id^1665|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_divanov_s.png|caption^null|alt^ПЕРЕТЯЖКА ДИВАНОВ|title^ПЕРЕТЯЖКА ДИВАНОВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazka-divana%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_column_text]<iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Когда дорогие сердцу предметы теряют привлекательный облик, на ум приходит два типа решений: использовать эту мебель, например, на даче, или расстаться с ней навсегда. Но не торопитесь относить кресла или диван с изношенной тканью на свалку, ведь существует еще вариант перетяжки мебели. На этом этапе возникают сложности в поиске подходящей компании, которая сможет не просто перетянуть диван, но и досконально повторить все детали, элементы декора, особенности кроя.</p>\r\n<p style=\"text-indent: 25px;\">Крафтман предоставляет качественные услуги по перетяжке мебели в Москве. Существуя на рынке уже более тридцати лет, компания имеет огромный опыт, а главное, с любовью подходит к своему делу. Специалисты используют материалы премиального качества, а также передовое оборудование, что позволяет осуществить перетяжку мебели в Москве на самом высоком уровне.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row]', '', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-07-25 19:50:39', '2018-07-25 16:50:39', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
