obile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА КОЖАНОЙ МЕБЕЛИ\" thumb_img=\"id^1667|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_kozhej_s.png|caption^null|alt^ПЕРЕТЯЖКА КОЖЕЙ|title^ПЕРЕТЯЖКА КОЖЕЙ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-kozhej%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ\" thumb_img=\"id^1666|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyagka_myagkoy_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|title^ПЕРЕТЯЖКА МЯГКОЙ МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-myagkoj-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" thumb_img=\"id^1669|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_stulev_s.png|caption^null|alt^ПЕРЕТЯЖКА СТУЛЬЕВ|title^ПЕРЕТЯЖКА СТУЛЬЕВ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fperetyazhka-stulev%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][ult_ihover_item title=\"ПЕРЕТЯЖКА МЕБЕЛИ\" thumb_img=\"id^1668|url^https://kraftman.ru/wp-content/uploads/2016/10/peretyajka_mebeli_s.png|caption^null|alt^ПЕРЕТЯЖКА МЕБЕЛИ|title^ПЕРЕТЯЖКА МЕБЕЛИ|description^null\" block_click=\"link\" block_link=\"url:https%3A%2F%2Fkraftman.ru%2Fportfolio%2Fperetyazhka-mebeli%2F|||\" title_responsive_font_size=\"desktop:18px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" title_responsive_line_height=\"desktop:19px;tablet_portrait:16px;mobile_landscape:12px;mobile:10px;\" desc_responsive_font_size=\"desktop:12px;\" desc_responsive_line_height=\"desktop:18px;\"][/ult_ihover_item][/ult_ihover][/vc_column][/vc_row][vc_row css=\".vc_custom_1532796361285{padding-top: 50px !important;}\"][vc_column][vc_custom_heading text=\"Производство\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:35px\" css=\".vc_custom_1533302029232{padding-top: 0px !important;padding-left: 0px !important;}\"][/vc_column][/vc_row][vc_row content_placement=\"middle\"][vc_column][vc_column_text]\r\n<p style=\"text-align: left;\"><span style=\"font-weight: 400;\">Крафтман предоставляет услуги по перетяжке мебели в Москве  уже более тридцати лет. Компания имеет огромный опыт, а главное, с любовью подходит к своему делу. </span><span style=\"font-weight: 400;\">В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты. Все это позволяет осуществить перетяжку мебели в Москве быстро и качественно.</span></p>\r\n<p style=\"text-align: left;\"><span style=\"font-weight: 400;\">Оценить образцы тканей и кожи можно в шоуруме, который находится в центре Москвы и заранее выбрать подходящий вариант.</span></p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1533244434606{padding-top: 20px !important;padding-bottom: 20px !important;}\"][vc_column][vc_column_text]<iframe style=\"margin: 0 auto; width: 80%; display: block;\" src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" height=\"515\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe>[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532796361285{padding-top: 50px !important;}\"][vc_column][vc_custom_heading text=\"Наши преимущества\" font_container=\"tag:h1|font_size:30px|text_align:left|line_height:35px\" css=\".vc_custom_1533301594258{padding-top: 0px !important;padding-left: 0px !important;}\"][/vc_column][/vc_row][vc_row css=\".vc_custom_1532538038638{padding-right: 15px !important;padding-bottom: 50px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"3623\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Собственный магазин мебельных материалов</h2>\r\n[/vc_column_text][vc_column_text][/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3624\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Бесплатный выезд дизайнера с образцами</h2>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3622\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Семейные традиции с 1986-го года</h2>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3625\" size=\"full\" align=\"center\"][vc_column_text]\r\n<h2 style=\"text-align: center; font-size: 18px !important;\">Расширенный срок гарантии на выполненные работы - 3 года</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row height=\"auto\" disable_element=\"yes\" css=\".vc_custom_1533301764215{padding-top: 50px !important;}\"][vc_column][vc_custom_heading text=\"Вы ещё думаете? Скорее возьмите телефон и звоните\" font_container=\"tag:h3|font_size:30px|text_align:center|line_height:35px\" css=\".vc_custom_1532839937170{padding-top: 0px !important;padding-left: 0px !important;}\"][/vc_column][/vc_row][vc_row disable_element=\"yes\" css=\".vc_custom_1532785936961{padding-bottom: 50px !important;}\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Преимущества работы с Крафтман</h2>\r\n<ul>\r\n 	<li>Компания предлагает сервис самого высокого уровня. В мастерской используются качественные материалы от элитных мировых производителей и современное оборудование, на котором работают высококвалифицированные специалисты.</li>\r\n 	<li>Собственная служба доставки.</li>\r\n 	<li>Возможность оценить образцы тканей в шоу-руме, который находится в центре Москвы, и заранее выбрать подходящий вариант.</li>\r\n 	<li>Расширенный срок гарантии на выполненные работы - 3 года.</li>\r\n 	<li>Каждый новый заказ - это отдельный авторский проект со своим дизайнером и технологом, требующий индивидуального подхода, а зачастую и нестандартных решений.</li>\r\n 	<li>Качественная перетяжка мебели и выгодные цены.</li>\r\n 	<li>Опыт работы с 1986 года.</li>\r\n 	<li>Компания “Крафтман” успешно сотрудничает с ведущими мировыми брендами.</li>\r\n 	<li>Оценить фото выполненных работ можно в нашем портфолио.</li>\r\n</ul>\r\nВы еще думаете? Скорее возьмите телефон и звоните![/vc_column_text][/vc_column][/vc_row][vc_row content_placement=\"bottom\" columns_type=\"none\" height=\"auto\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3415|url^https://kraftman.ru/wp-content/uploads/2018/07/Pasted_image_at_2017.png|caption^null|alt^null|title^Pasted_image_at_2017|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" css=\".vc_custom_1532793325899{margin-top: 0px !important;margin-right: 0px !important;margin-bottom: 0px !important;margin-left: 0px !important;border-top-width: 0px !important;border-right-width: 0px !important;border-bottom-width: 0px !important;border-left-width: 0px !important;padding-top: 0px !important;padding-right: 0px !important;padding-bottom: 0px !important;padding-left: 0px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row content_placement=\"middle\" css=\".vc_custom_1533304727070{padding-top: 50px !important;padding-bottom: 50px !important;}\" el_class=\"pc\"][vc_column width=\"1/3\"][vc_column_text]<span style=\"text-decoration: underline;\">перетяжка кресел</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка стульев</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка дивана</span>[/vc_column_text][/vc_column][vc_column width=\"1/3\"][vc_column_text]<span style=\"text-decoration: underline;\">перетяжка дивана кожей</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка изголовья кроватей</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка кожанной мебели</span>[/vc_column_text][/vc_column][vc_column width=\"1/3\"][vc_column_text]<span style=\"text-decoration: underline;\">перетяжка кухонного уголка</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка кресла руководителя</span>\r\n\r\n<span style=\"text-decoration: underline;\">пиковка мебели</span>[/vc_column_text][/vc_column][/vc_row][vc_row content_placement=\"middle\" css=\".vc_custom_1533304888352{padding-top: 50px !important;padding-bottom: 50px !important;}\" el_class=\"mob mob2c\"][vc_column width=\"1/2\"][vc_column_text]<span style=\"text-decoration: underline;\">перетяжка кресел</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка стульев</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка дивана</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка дивана кожей</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка кухонного уголка</span>[/vc_column_text][/vc_column][vc_column width=\"1/2\"][vc_column_text]<span style=\"text-decoration: underline;\">перетяжка изголовья кроватей</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка кожанной мебели</span>\r\n\r\n<span style=\"text-decoration: underline;\">перетяжка кресла руководителя</span>\r\n\r\n<span style=\"text-decoration: underline;\">пиковка мебели</span>[/vc_column_text][/vc_column][/vc_row]', 't', '', 'inherit', 'closed', 'closed', '', '10-revision-v1', '', '', '2018-08-06 18:07:06', '2018-08-06 15:07:06', '', 10, 'https://kraftman.ru/10-revision-v1/', 0, 'revision', '', 0),
