(3669, 1, '2018-08-07 00:51:29', '2018-08-06 21:51:29', '[vc_row][vc_column][vc_custom_heading text=\"Широкий ассортимент тканей и кожи\" font_container=\"tag:h1|font_size:62|text_align:center\" google_fonts=\"font_family:Roboto%3A100%2C100italic%2C300%2C300italic%2Cregular%2Citalic%2C500%2C500italic%2C700%2C700italic%2C900%2C900italic|font_style:400%20regular%3A400%3Anormal\"][vc_column_text el_class=\"begtxt\"]\n<p style=\"text-align: center;\">Любые обивочные материалы по Вашему индивидуальному запросу. В шоу - руме Крафтман, на Китай-городе, Вы сможете подобрать именно ту обивку, которую ищите!\nПридумайте свой рисунок, и мы поможем подобрать именно такой.\n\n[/vc_column_text][vc_custom_heading text=\"Выезд дизайнера с каталогами - бесплатно!\" font_container=\"tag:h1|text_align:center\" google_fonts=\"font_family:Roboto%3A100%2C100italic%2C300%2C300italic%2Cregular%2Citalic%2C500%2C500italic%2C700%2C700italic%2C900%2C900italic|font_style:400%20regular%3A400%3Anormal\"][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Основные свойства материалов\" font_container=\"tag:h3|text_align:center\" google_fonts=\"font_family:Roboto%3A100%2C100italic%2C300%2C300italic%2Cregular%2Citalic%2C500%2C500italic%2C700%2C700italic%2C900%2C900italic|font_style:400%20regular%3A400%3Anormal\"][/vc_column][/vc_row][vc_row][vc_column width=\"1/2\"][vc_row_inner][vc_column_inner width=\"1/4\"][us_single_image image=\"3655\"][/vc_column_inner][vc_column_inner width=\"3/4\"][vc_column_text css=\".vc_custom_1533587523366{padding-top: 20px !important;}\"]Устойчивость к загрязнениям[/vc_column_text][/vc_column_inner][/vc_row_inner][vc_row_inner][vc_column_inner width=\"1/4\"][us_single_image image=\"3654\"][/vc_column_inner][vc_column_inner width=\"3/4\"][vc_column_text css=\".vc_custom_1533587505170{padding-top: 20px !important;}\"]\n<div class=\"t493__item t493__item_padding-top t-item\">\n<div class=\"t493__textwrapper t-cell t-valign_top\">\n<div class=\"t493__heading t