c;\">от 3650 руб.</td>\r\n<td class=\"t431__td\" style=\"font-size: inherit; border-width: 1px; border-color: #807c7c; color: #4d4c4c;\">Стул</td>\r\n<td class=\"t431__td\" style=\"font-size: inherit; border-width: 1px; border-color: #807c7c; color: #4d4c4c;\">от 350 руб.</td>\r\n</tr>\r\n<tr class=\"t431__evenrow\" style=\"background: #eeeeee;\">\r\n<td class=\"t431__td\" style=\"font-size: inherit; border-width: 1px; border-color: #807c7c; color: #4d4c4c;\">Диван тройной</td>\r\n<td class=\"t431__td\" style=\"font-size: inherit; border-width: 1px; border-color: #807c7c; color: #4d4c4c;\">от 4400 руб.</td>\r\n<td class=\"t431__td\" style=\"font-size: inherit; border-width: 1px; border-color: #807c7c; color: #4d4c4c;\">Стул с мягкой спинкой</td>\r\n<td class=\"t431__td\" style=\"font-size: inherit; border-width: 1px; border-color: #807c7c; color: #4d4c4c;\">от 950 руб.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Для наиболее точной оценки стоимости звоните по указанному номеру телефона. Наши специалисты с радостью проконсультируют Вас!\" font_container=\"tag:h4|text_align:center\"][/vc_column][/vc_row][vc_row bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3689|url^https://kraftman.ru/wp-content/uploads/2018/08/avtobus.png|caption^null|alt^null|title^автобус|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" disable_on_mobile_img_parallax=\"disable_on_mobile_img_parallax_value\" css=\".vc_custom_1533757246708{padding-top: 100px !important;padding-bottom: 100px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row]', 'Цены', '', 'inherit', 'closed', 'closed', '', '3694-revision-v1', '', '', '2018-08-10 21:24:51', '2018-08-10 18:24:51', '', 3694, 'https://kraftman.ru/3694-revision-v1/', 0, 'revision', '', 0);
