(3809, 1, '2018-08-13 00:58:02', '2018-08-12 21:58:02', '', 'peretyajka-garnitur-', '', 'inherit', 'open', 'closed', '', 'peretyajka-garnitur-2', '', '', '2018-08-13 00:58:02', '2018-08-12 21:58:02', '', 2161, 'https://kraftman.ru/wp-content/uploads/2018/08/peretyajka-garnitur-1-1.jpg', 0, 'attachment', 'image/jpeg', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3810, 1, '2018-08-13 00:58:13', '2018-08-12 21:58:13', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3469|url^https://kraftman.ru/wp-content/uploads/2018/07/22.jpg|caption^null|alt^null|title^22|description^null\" bg_override=\"full\" el_class=\"glavsl\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row el_class=\"onlmo\"][vc_column][vc_custom_heading text=\"ПЕРЕТЯЖКА СТУЛЬЕВ\" font_container=\"tag:h1|text_align:center\"][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<p style=\"text-indent: 25px;\">Стулья относятся к числу самой часто используемой мебели, поэтому максимально подвержены износу. Когда обивка сидения потеряла привлекательный внешний вид, а сам корпус остался в хорошем состоянии, отличным решением может стать перетяжка стульев.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/peretyzhka-stulev-do.png\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/peretyzhka-stulev-posle.png\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row el_class=\"mob\"][vc_column][vc_raw_html]JTNDaDElMjBzdHlsZSUzRCUyMmNvbG9yJTNBJTIwJTIzMDAwJTNCJTIwdGV4dC10cmFuc2Zvcm0lM0ElMjB1cHBlcmNhc2UlM0IlMjIlM0UlRDAlOUYlRDAlOTUlRDAlQTAlRDAlOTUlRDAlQTIlRDAlQUYlRDAlOTYlRDAlOUElRDAlOTAlMjAlRDAlQTElRDAlQTIlRDAlQTMlRDAlOUIlRDAlQUMlRDAlOTUlRDAlOTIlM0MlMkZoMSUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Этапы работ\" font_container=\"tag:h1|text_align:left\"][vc_column_text]\r\n<p style=\"text-align: center;\">Мебельная мастерская Крафтман — компания, которая несколько десятилетий занимается ремонтом и перетяжкой стульев в Москве, недорого предлагая услуги высокого качества. Над преображением мебели работает команда профессиональных мастеров, которые используют материалы от мировых производителей и выполняют работу на высококлассном оборудовании. Все это позволяет компании Крафман гарантировать высокий результат и перетянуть стулья для по выгодной стоимости.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532538038638{padding-right: 15px !important;padding-bottom: 50px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Вызовите дизайнера</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Согласуйте обивочный материал</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Согласуйте даты транспортировки</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Наслаждайтесь результатом</strong></h4>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][rev_slider_vc alias=\"peretyagka_mebeli\"][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column width=\"2/3\"][vc_row_inner][vc_column_inner width=\"1/2\"][vc_column_text]\r\n<p style=\"text-align: center;\">Было</p>\r\n[/vc_column_text][us_single_image image=\"2162\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][vc_column_inner width=\"1/2\"][vc_column_text]\r\n<p style=\"text-align: center;\">Стало</p>\r\n[/vc_column_text][us_single_image image=\"2163\" size=\"medium\" align=\"center\" lightbox=\"1\"][us_single_image image=\"219\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][/vc_row_inner][/vc_column][vc_column width=\"1/3\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Что включают в себя работы</h2>\r\n<p style=\"text-indent: 25px;\">Стандартный набор услуг, характерный как для перетяжки кухонных стульев, так и для других их видов, состоит из частичной реставрации предметов: удаление с поверхности грязи и царапин. Также производится замена ткани, наполнителя и отделка тесьмой. Предварительно к вам приезжает представитель компании и показывает образцы материалов, подробно консультируя о необходимых работах.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Эффективное решение главных проблем</h2>\r\n<p style=\"text-indent: 25px;\">Перетяжка стульев в Москве может потребоваться, когда обладатель хорошей и дорогой мебели заметил ее естественный износ: обивка устарела или на корпусе появились царапины. Когда могут потребоваться специалисты для перетяжки сидений стульев?</p>\r\n\r\n<ul>\r\n 	<li>Когда речь идет о старинной мебели, важна деликатность и точность. Сложно выполнить перетяжку стульев самостоятельно, не повредив декоративную отделку, цена ошибки тут крайне высока. Качественная перетяжка стула позволяет не только обновить обивку, но и сохранить индивидуальность мягкой мебели.</li>\r\n 	<li>Выбор ткани - не такая простая задача, как может показаться на первый взгляд. Производители предлагают широкий выбор материалов разных видов. Специалист помогает клиенту сориентироваться, какую ткань лучше покупать, если нужна перетяжка барных стульев, и требуется ли в конкретном случае обивка стульев кожей.</li>\r\n 	<li>Профессионал сможет точно определить, когда необходима замена не только обивки, но и наполнителя. Это позволит сразу понять, сколько стоит весь перечень работ, а также выполнить их на должном уровне.</li>\r\n</ul>\r\n<p style=\"text-indent: 25px;\">Решением всех проблем перетяжки мебели станет обращение в мастерскую “Крафтман”, вы можете не сомневаться, что стулья прослужат вам еще очень долго.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row columns_type=\"none\" height=\"auto\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3569|url^https://kraftman.ru/wp-content/uploads/2018/08/shutterstock_407663188-1.jpg|caption^Industrial sewing machine for leather/ Closeup of sewing machine working part with leather; Shutterstock ID 407663188; Purchase Order: -|alt^null|title^shutterstock_407663188 (1)|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" css=\".vc_custom_1534080892175{padding-top: 0px !important;padding-bottom: 0px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Благодарственные письма от ведущих компаний</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<h3 style=\"text-align: center;\">Преимущества компании Крафтман</h3>\r\n<ul>\r\n 	<li>Сотрудники компании реализуют индивидуальный подход к клиенту, учитывая потребности каждого. Они способны идеально повторить любой шов и реализовать самые сложные идеи.</li>\r\n 	<li>Каждый проект мебельной мастерской - это авторская работа квалифицированных мастеров с огромным опытом. “Крафтман” превращает старые вещи в настоящее произведение искусства.</li>\r\n 	<li>Мастерская обладает всеми техническими возможностями для качественной работы.</li>\r\n 	<li>Гарантия три года.</li>\r\n</ul>\r\n<p style=\"text-indent: 25px;\">Оставляйте заявки у наших менеджеров, чтобы подарить Вашей мебели новую жизнь!</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<div style=\"width: 560px; margin: auto;\"><iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Описание работ по перетяжке и реставрации стульев для столовой\" font_container=\"tag:h1|text_align:center\"][vc_column_text]\r\n<p style=\"text-align: center;\">Стандартный набор услуг, характерный как для перетяжки кухонных стульев, так и для других их видов, состоит из частичной реставрации предметов: удаление с поверхности грязи и царапин. Также производится замена ткани, наполнителя и отделка тесьмой или гвоздиком. Предварительно к вам приезжает представитель компании и показывает образцы материалов, подробно консультируя о необходимых работах.</p>\r\n[/vc_column_text][us_single_image image=\"3783\" size=\"full\" align=\"center\"][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Преимущества компании Крафтман\" font_container=\"tag:h1|text_align:center\"][/vc_column][/vc_row][vc_row][vc_column width=\"1/4\"][us_single_image image=\"3627\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Собственный магазин обивочных материалов</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3788\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Высокотехнологичное оборудование</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3630\" size=\"medium\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Гарантия на работы 3 года</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3809\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Собственная служба доставки</strong></h4>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3689|url^https://kraftman.ru/wp-content/uploads/2018/08/avtobus.png|caption^null|alt^null|title^автобус|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" disable_on_mobile_img_parallax=\"disable_on_mobile_img_parallax_value\" css=\".vc_custom_1533942966165{padding-top: 100px !important;padding-bottom: 100px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row]', 'Перетяжка стульев', '', 'inherit', 'closed', 'closed', '', '2161-revision-v1', '', '', '2018-08-13 00:58:13', '2018-08-12 21:58:13', '', 2161, 'https://kraftman.ru/2161-revision-v1/', 0, 'revision', '', 0),
(3811, 1, '2018-08-13 00:58:50', '2018-08-12 21:58:50', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3469|url^https://kraftman.ru/wp-content/uploads/2018/07/22.jpg|caption^null|alt^null|title^22|description^null\" bg_override=\"full\" el_class=\"glavsl\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row el_class=\"onlmo\"][vc_column][vc_custom_heading text=\"ПЕРЕТЯЖКА ДИВАНА\" font_container=\"tag:h1|text_align:center\"][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<p style=\"text-indent: 25px; text-align: center;\">Диваны относят к мебели с ограниченным сроком эксплуатации. От частого трения изнашивается обивка, которой в определенный момент требуется замена. Перетяжка дивана — универсальное решение этой проблемы.\r\nМастерская \"Крафтман\" произведет перетяжку дивана недорого и на высоком уровне. Благодаря тридцатилетнему опыту работы, перетяжка диванов осуществляется в срок и в любом объеме.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/peretyzhka-stulev-do.png\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/peretyzhka-stulev-posle.png\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row el_class=\"mob\"][vc_column][vc_raw_html]JTNDaDElMjBzdHlsZSUzRCUyMmNvbG9yJTNBJTIwJTIzMDAwJTNCJTIwdGV4dC10cmFuc2Zvcm0lM0ElMjB1cHBlcmNhc2UlM0IlMjIlM0UlRDAlOUYlRDAlOTUlRDAlQTAlRDAlOTUlRDAlQTIlRDAlQUYlRDAlOTYlRDAlOUElRDAlOTAlMjAlRDAlQTElRDAlQTIlRDAlQTMlRDAlOUIlRDAlQUMlRDAlOTUlRDAlOTIlM0MlMkZoMSUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Этапы работ\" font_container=\"tag:h1|text_align:left\"][vc_column_text]\r\n<div id=\"rec62864112\" class=\"r t-rec t-rec_pt_15 t-rec_pb_0 r_anim r_showed\" data-record-type=\"30\">\r\n<div class=\"t015\">\r\n<div class=\"t-container t-align_center\">\r\n<div class=\"t-col t-col_12 \">\r\n<div class=\"t015__descr t-descr t-descr_xl\">\r\n<div data-customstyle=\"yes\">\r\n<div style=\"text-align: center;\" data-customstyle=\"yes\">При необходимости перетянуть диван возникает ряд трудностей. Для качественной перетяжки дивана нужно решить достаточно большое количество задач, требующих определенный опыт и уровень мастерства . Мебель необходимо разобрать, пошить новый чехол по лекалам от старой обивки дивана, обить с использованием профессионального оборудования. Часто, требуется не только перетянуть, но и выполнить ремонт мягкой мебели.</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532538038638{padding-right: 15px !important;padding-bottom: 50px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Вызовите дизайнера</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Согласуйте обивочный материал</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Согласуйте даты транспортировки</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Наслаждайтесь результатом</strong></h4>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][rev_slider_vc alias=\"peretyagka_mebeli\"][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column width=\"2/3\"][vc_row_inner][vc_column_inner width=\"1/2\"][vc_column_text]\r\n<p style=\"text-align: center;\">Было</p>\r\n[/vc_column_text][us_single_image image=\"2162\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][vc_column_inner width=\"1/2\"][vc_column_text]\r\n<p style=\"text-align: center;\">Стало</p>\r\n[/vc_column_text][us_single_image image=\"2163\" size=\"medium\" align=\"center\" lightbox=\"1\"][us_single_image image=\"219\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][/vc_row_inner][/vc_column][vc_column width=\"1/3\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Что включают в себя работы</h2>\r\n<p style=\"text-indent: 25px;\">Стандартный набор услуг, характерный как для перетяжки кухонных стульев, так и для других их видов, состоит из частичной реставрации предметов: удаление с поверхности грязи и царапин. Также производится замена ткани, наполнителя и отделка тесьмой. Предварительно к вам приезжает представитель компании и показывает образцы материалов, подробно консультируя о необходимых работах.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<p style=\"text-align: center;\">Подбор материала для перетяжки обивки дивана — не такая простая задача, как может показаться на первый взгляд. При разнообразии материалов для обтяжки довольно сложно подобрать подходящий вариант ткани для обивки дивана с корректным соотношением цены и качества.</p>\r\nПомимо этого, актуален вопрос о выгоде услуги. Важно понимать, сколько будет стоить работа мастера, обойдется ли перетяжка дивана недорого.\r\n\r\nМожно потратить много времени и сил для самостоятельного решения этих задач. Но лучшим вариантом будет обратиться к компанию \"Крафтман\". Специалисты проконсультируют Вас по всем вопросам, осуществят качественную перетяжку дивана по выгодной цене с предоставлением первоклассного сервиса\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row columns_type=\"none\" height=\"auto\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3569|url^https://kraftman.ru/wp-content/uploads/2018/08/shutterstock_407663188-1.jpg|caption^Industrial sewing machine for leather/ Closeup of sewing machine working part with leather; Shutterstock ID 407663188; Purchase Order: -|alt^null|title^shutterstock_407663188 (1)|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" css=\".vc_custom_1534080892175{padding-top: 0px !important;padding-bottom: 0px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Благодарственные письма от ведущих компаний</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<h3 style=\"text-align: center;\">Преимущества компании Крафтман</h3>\r\n<ul>\r\n 	<li>Сотрудники компании реализуют индивидуальный подход к клиенту, учитывая потребности каждого. Они способны идеально повторить любой шов и реализовать самые сложные идеи.</li>\r\n 	<li>Каждый проект мебельной мастерской - это авторская работа квалифицированных мастеров с огромным опытом. “Крафтман” превращает старые вещи в настоящее произведение искусства.</li>\r\n 	<li>Мастерская обладает всеми техническими возможностями для качественной работы.</li>\r\n 	<li>Гарантия три года.</li>\r\n</ul>\r\n<p style=\"text-indent: 25px;\">Оставляйте заявки у наших менеджеров, чтобы подарить Вашей мебели новую жизнь!</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<div style=\"width: 560px; margin: auto;\"><iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Пример работы перетяжки дивана\" font_container=\"tag:h1|text_align:center\"][vc_column_text]\r\n<p style=\"text-align: center;\">Примером профессиональной работы мастеров компании служит диван, перетянутый жаккардом. Этот материал был выбран, чтобы максимально приблизить предметы интерьера к классическому стилю.\r\nСложностей добавлял увеличенный рапорт рисунка и пласти лекал в 80 см. С такими условиями, очень тяжело поменять обшивку так, чтобы рисунок на различных частях кроя совпадал. Однако сотрудники \"Крафтмана\" справились с этой задачей и диван с изношенной обивкой превратился в дорогой предмет интерьера.</p>\r\n<p style=\"text-align: center;\">У вас есть обычный или угловой диван, который нужно изменить в лучшую сторону? Тогда торопитесь заказать услуги \"Крафтман\". Телефон для связи и фото работ вы можете найти на нашем сайте.</p>\r\n[/vc_column_text][us_single_image image=\"3808\" size=\"full\" align=\"center\"][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Преимущества компании Крафтман\" font_container=\"tag:h1|text_align:center\"][/vc_column][/vc_row][vc_row][vc_column width=\"1/4\"][us_single_image image=\"3627\" align=\"center\"][vc_column_text]\r\n<div class=\"t490__col t-col t-col_3 t-align_center t-item\">\r\n<div class=\"t490__wrappercenter \">\r\n<div class=\"t-heading t-heading_md\">\r\n<h4 style=\"text-align: center;\" data-customstyle=\"yes\"><strong>Собственный магазин мебельных материалов</strong></h4>\r\n</div>\r\n</div>\r\n</div>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3788\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Перетяжка дивана в Москве с помощью высокотехнологичного оборудования</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3630\" size=\"medium\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Расширенный срок гарантии на работы 3 года</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3791\" align=\"center\"][vc_column_text]\r\n<div id=\"rec62864120\" class=\"r t-rec t-rec_pt_90 t-rec_pt-res-480_45 t-rec_pb_90 t-screenmin-980px\" data-record-type=\"490\" data-screen-min=\"980px\">\r\n<div class=\"t490\">\r\n<div class=\"t-container\">\r\n<div class=\"t490__col t-col t-col_3 t-align_center t-item\">\r\n<div class=\"t490__wrappercenter \">\r\n<div class=\"t-heading t-heading_md\">\r\n<h4 style=\"text-align: center;\" data-customstyle=\"yes\"><strong>Привлекательные цены</strong></h4>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3689|url^https://kraftman.ru/wp-content/uploads/2018/08/avtobus.png|caption^null|alt^null|title^автобус|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" disable_on_mobile_img_parallax=\"disable_on_mobile_img_parallax_value\" css=\".vc_custom_1533942966165{padding-top: 100px !important;padding-bottom: 100px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row]', 'Перетяжка дивана', '', 'inherit', 'closed', 'closed', '', '2476-revision-v1', '', '', '2018-08-13 00:58:50', '2018-08-12 21:58:50', '', 2476, 'https://kraftman.ru/2476-revision-v1/', 0, 'revision', '', 0),
(3812, 1, '2018-08-13 01:07:10', '2018-08-12 22:07:10', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3469|url^https://kraftman.ru/wp-content/uploads/2018/07/22.jpg|caption^null|alt^null|title^22|description^null\" bg_override=\"full\" el_class=\"glavsl\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row el_class=\"onlmo\"][vc_column][vc_custom_heading text=\"ПЕРЕТЯЖКА ДИВАНА\" font_container=\"tag:h1|text_align:center\"][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<p style=\"text-indent: 25px; text-align: center;\">Диваны относят к мебели с ограниченным сроком эксплуатации. От частого трения изнашивается обивка, которой в определенный момент требуется замена. Перетяжка дивана — универсальное решение этой проблемы.\r\nМастерская \"Крафтман\" произведет перетяжку дивана недорого и на высоком уровне. Благодаря тридцатилетнему опыту работы, перетяжка диванов осуществляется в срок и в любом объеме.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/peretyzhka-stulev-do.png\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/peretyzhka-stulev-posle.png\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row el_class=\"mob\"][vc_column][vc_raw_html]JTNDaDElMjBzdHlsZSUzRCUyMmNvbG9yJTNBJTIwJTIzMDAwJTNCJTIwdGV4dC10cmFuc2Zvcm0lM0ElMjB1cHBlcmNhc2UlM0IlMjIlM0UlRDAlOUYlRDAlOTUlRDAlQTAlRDAlOTUlRDAlQTIlRDAlQUYlRDAlOTYlRDAlOUElRDAlOTAlMjAlRDAlQTElRDAlQTIlRDAlQTMlRDAlOUIlRDAlQUMlRDAlOTUlRDAlOTIlM0MlMkZoMSUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Этапы работ\" font_container=\"tag:h1|text_align:left\"][vc_column_text]\r\n<p style=\"text-align: center;\">При необходимости перетянуть диван возникает ряд трудностей. Для качественной перетяжки дивана нужно решить достаточно большое количество задач, требующих определенный опыт и уровень мастерства . Мебель необходимо разобрать, пошить новый чехол по лекалам от старой обивки дивана, обить с использованием профессионального оборудования. Часто, требуется не только перетянуть, но и выполнить ремонт мягкой мебели.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532538038638{padding-right: 15px !important;padding-bottom: 50px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Вызовите дизайнера</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Согласуйте обивочный материал</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Согласуйте даты транспортировки</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Наслаждайтесь результатом</strong></h4>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][rev_slider_vc alias=\"peretyagka_mebeli\"][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column width=\"2/3\"][vc_row_inner][vc_column_inner width=\"1/2\"][vc_column_text]\r\n<p style=\"text-align: center;\">Было</p>\r\n[/vc_column_text][us_single_image image=\"2162\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][vc_column_inner width=\"1/2\"][vc_column_text]\r\n<p style=\"text-align: center;\">Стало</p>\r\n[/vc_column_text][us_single_image image=\"2163\" size=\"medium\" align=\"center\" lightbox=\"1\"][us_single_image image=\"219\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][/vc_row_inner][/vc_column][vc_column width=\"1/3\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Что включают в себя работы</h2>\r\n<p style=\"text-indent: 25px;\">Стандартный набор услуг, характерный как для перетяжки кухонных стульев, так и для других их видов, состоит из частичной реставрации предметов: удаление с поверхности грязи и царапин. Также производится замена ткани, наполнителя и отделка тесьмой. Предварительно к вам приезжает представитель компании и показывает образцы материалов, подробно консультируя о необходимых работах.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]\r\n<p style=\"text-align: center;\">Подбор материала для перетяжки обивки дивана — не такая простая задача, как может показаться на первый взгляд. При разнообразии материалов для обтяжки довольно сложно подобрать подходящий вариант ткани для обивки дивана с корректным соотношением цены и качества.</p>\r\n<p style=\"text-align: center;\">Помимо этого, актуален вопрос о выгоде услуги. Важно понимать, сколько будет стоить работа мастера, обойдется ли перетяжка дивана недорого.</p>\r\n<p style=\"text-align: center;\">Можно потратить много времени и сил для самостоятельного решения этих задач. Но лучшим вариантом будет обратиться к компанию \"Крафтман\". Специалисты проконсультируют Вас по всем вопросам, осуществят качественную перетяжку дивана по выгодной цене с предоставлением первоклассного сервиса</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row columns_type=\"none\" height=\"auto\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3569|url^https://kraftman.ru/wp-content/uploads/2018/08/shutterstock_407663188-1.jpg|caption^Industrial sewing machine for leather/ Closeup of sewing machine working part with leather; Shutterstock ID 407663188; Purchase Order: -|alt^null|title^shutterstock_407663188 (1)|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" css=\".vc_custom_1534080892175{padding-top: 0px !important;padding-bottom: 0px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Благодарственные письма от ведущих компаний</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<h3 style=\"text-align: center;\">Преимущества компании Крафтман</h3>\r\n<ul>\r\n 	<li>Сотрудники компании реализуют индивидуальный подход к клиенту, учитывая потребности каждого. Они способны идеально повторить любой шов и реализовать самые сложные идеи.</li>\r\n 	<li>Каждый проект мебельной мастерской - это авторская работа квалифицированных мастеров с огромным опытом. “Крафтман” превращает старые вещи в настоящее произведение искусства.</li>\r\n 	<li>Мастерская обладает всеми техническими возможностями для качественной работы.</li>\r\n 	<li>Гарантия три года.</li>\r\n</ul>\r\n<p style=\"text-indent: 25px;\">Оставляйте заявки у наших менеджеров, чтобы подарить Вашей мебели новую жизнь!</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<div style=\"width: 560px; margin: auto;\"><iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Пример работы перетяжки дивана\" font_container=\"tag:h1|text_align:center\"][vc_column_text]\r\n<p style=\"text-align: center;\">Примером профессиональной работы мастеров компании служит диван, перетянутый жаккардом. Этот материал был выбран, чтобы максимально приблизить предметы интерьера к классическому стилю.\r\nСложностей добавлял увеличенный рапорт рисунка и пласти лекал в 80 см. С такими условиями, очень тяжело поменять обшивку так, чтобы рисунок на различных частях кроя совпадал. Однако сотрудники \"Крафтмана\" справились с этой задачей и диван с изношенной обивкой превратился в дорогой предмет интерьера.</p>\r\n<p style=\"text-align: center;\">У вас есть обычный или угловой диван, который нужно изменить в лучшую сторону? Тогда торопитесь заказать услуги \"Крафтман\". Телефон для связи и фото работ вы можете найти на нашем сайте.</p>\r\n[/vc_column_text][us_single_image image=\"3808\" size=\"full\" align=\"center\"][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Преимущества компании Крафтман\" font_container=\"tag:h1|text_align:center\"][/vc_column][/vc_row][vc_row][vc_column width=\"1/4\"][us_single_image image=\"3627\" align=\"center\"][vc_column_text]\r\n<div class=\"t490__col t-col t-col_3 t-align_center t-item\">\r\n<div class=\"t490__wrappercenter \">\r\n<div class=\"t-heading t-heading_md\">\r\n<h4 style=\"text-align: center;\" data-customstyle=\"yes\"><strong>Собственный магазин мебельных материалов</strong></h4>\r\n</div>\r\n</div>\r\n</div>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3788\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Перетяжка дивана в Москве с помощью высокотехнологичного оборудования</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3630\" size=\"medium\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Расширенный срок гарантии на работы 3 года</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3791\" align=\"center\"][vc_column_text]\r\n<div id=\"rec62864120\" class=\"r t-rec t-rec_pt_90 t-rec_pt-res-480_45 t-rec_pb_90 t-screenmin-980px\" data-record-type=\"490\" data-screen-min=\"980px\">\r\n<div class=\"t490\">\r\n<div class=\"t-container\">\r\n<div class=\"t490__col t-col t-col_3 t-align_center t-item\">\r\n<div class=\"t490__wrappercenter \">\r\n<div class=\"t-heading t-heading_md\">\r\n<h4 style=\"text-align: center;\" data-customstyle=\"yes\"><strong>Привлекательные цены</strong></h4>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3689|url^https://kraftman.ru/wp-content/uploads/2018/08/avtobus.png|caption^null|alt^null|title^автобус|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" disable_on_mobile_img_parallax=\"disable_on_mobile_img_parallax_value\" css=\".vc_custom_1533942966165{padding-top: 100px !important;padding-bottom: 100px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row]', 'Перетяжка дивана', '', 'inherit', 'closed', 'closed', '', '2476-revision-v1', '', '', '2018-08-13 01:07:10', '2018-08-12 22:07:10', '', 2476, 'https://kraftman.ru/2476-revision-v1/', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(3813, 1, '2018-08-13 01:09:30', '2018-08-12 22:09:30', '[vc_row columns_type=\"none\" height=\"full\" valign=\"center\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3469|url^https://kraftman.ru/wp-content/uploads/2018/07/22.jpg|caption^null|alt^null|title^22|description^null\" bg_override=\"full\" el_class=\"glavsl\"][vc_column][vc_raw_html][/vc_raw_html][vc_raw_html el_class=\"caretdown\"][/vc_raw_html][/vc_column][/vc_row][vc_row el_class=\"onlmo\"][vc_column][vc_custom_heading text=\"ПЕРЕТЯЖКА ДИВАНА КОЖЕЙ\" font_container=\"tag:h1|text_align:center\"][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]<p style=\"text-align: center;\">Перетяжка мебели кожей — важное направление работы в мебельной мастерской Крафтман. Под воздействием внешней среды и механических повреждений обивка предметов интерьера теряет прежний привлекательный вид. Выходом из ситуации становится обращение к специалистам для осуществления перетяжки кожаной мягкой мебели.\r\nКомпания \"Крафтман\" предлагает услуги высокого качества по замене кожаной обивки в Москве в короткие сроки и по доступной стоимости.\r\nДля осуществления перетяжки мебели используется современное оборудование и качественные материалы. \"Крафтман\" занимается перетяжкой кожаных диванов в Москве более тридцати лет. За это время компания заслужила доверие большого числа клиентов.</p>[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/peretyzhka-stulev-do.png\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/4/peretyzhka-stulev-posle.png\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_raw_html el_class=\"iframe-calc\"][/vc_raw_html][/vc_column][/vc_row][vc_row el_class=\"mob\"][vc_column][vc_raw_html]JTNDaDElMjBzdHlsZSUzRCUyMmNvbG9yJTNBJTIwJTIzMDAwJTNCJTIwdGV4dC10cmFuc2Zvcm0lM0ElMjB1cHBlcmNhc2UlM0IlMjIlM0UlRDAlOUYlRDAlOTUlRDAlQTAlRDAlOTUlRDAlQTIlRDAlQUYlRDAlOTYlRDAlOUElRDAlOTAlMjAlRDAlQTElRDAlQTIlRDAlQTMlRDAlOUIlRDAlQUMlRDAlOTUlRDAlOTIlM0MlMkZoMSUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Этапы работ\" font_container=\"tag:h1|text_align:left\"][vc_column_text]\r\n<p style=\"text-align: center;\">Мебельная мастерская Крафтман — компания, которая несколько десятилетий занимается ремонтом и перетяжкой стульев в Москве, недорого предлагая услуги высокого качества. Над преображением мебели работает команда профессиональных мастеров, которые используют материалы от мировых производителей и выполняют работу на высококлассном оборудовании. Все это позволяет компании Крафман гарантировать высокий результат и перетянуть стулья для по выгодной стоимости.</p>\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row css=\".vc_custom_1532538038638{padding-right: 15px !important;padding-bottom: 50px !important;padding-left: 15px !important;}\"][vc_column width=\"1/4\"][us_single_image image=\"2369\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Вызовите дизайнера</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2437\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Согласуйте обивочный материал</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2390\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Согласуйте даты транспортировки</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"2391\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Наслаждайтесь результатом</strong></h4>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][rev_slider_vc alias=\"peretyagka_mebeli\"][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column width=\"2/3\"][vc_row_inner][vc_column_inner width=\"1/2\"][vc_column_text]\r\n<p style=\"text-align: center;\">Было</p>\r\n\r\n[/vc_column_text][us_single_image image=\"2162\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][vc_column_inner width=\"1/2\"][vc_column_text]\r\n<p style=\"text-align: center;\">Стало</p>\r\n\r\n[/vc_column_text][us_single_image image=\"2163\" size=\"medium\" align=\"center\" lightbox=\"1\"][us_single_image image=\"219\" size=\"medium\" align=\"center\" lightbox=\"1\"][/vc_column_inner][/vc_row_inner][/vc_column][vc_column width=\"1/3\"][vc_column_text]\r\n<h2 style=\"text-align: center;\">Что включают в себя работы</h2>\r\n<p style=\"text-indent: 25px;\">Стандартный набор услуг, характерный как для перетяжки кухонных стульев, так и для других их видов, состоит из частичной реставрации предметов: удаление с поверхности грязи и царапин. Также производится замена ткани, наполнителя и отделка тесьмой. Предварительно к вам приезжает представитель компании и показывает образцы материалов, подробно консультируя о необходимых работах.</p>\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_column_text]<ul>\r\n 	<li style=\"text-align: left;\">Перетяжка дивана кожей - это авторская работа команды высококлассных специалистов, а не конвеер однотипных изделий. В итоге, заказчик получает по-настоящему уникальный предмет интерьера.</li>\r\n 	<li style=\"text-align: left;\">Предоставление первоклассного сервиса и качественной работы недорого и в срок.</li>\r\n 	<li style=\"text-align: left;\">Диванная обтяжка выполняется из премиальных материалов мировых производителей.</li>\r\n 	<li style=\"text-align: left;\">Мастера работают как с натуральной кожей, так и кожзамом и экокожей.</li>\r\n</ul>[/vc_column_text][/vc_column][/vc_row][vc_row columns_type=\"none\" height=\"auto\" width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3569|url^https://kraftman.ru/wp-content/uploads/2018/08/shutterstock_407663188-1.jpg|caption^Industrial sewing machine for leather/ Closeup of sewing machine working part with leather; Shutterstock ID 407663188; Purchase Order: -|alt^null|title^shutterstock_407663188 (1)|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" css=\".vc_custom_1534080892175{padding-top: 0px !important;padding-bottom: 0px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<h2 style=\"text-align: center;\">Благодарственные письма от ведущих компаний</h2>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text][feedback][/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<h3 style=\"text-align: center;\">Преимущества компании Крафтман</h3>\r\n<ul>\r\n	<li>Сотрудники компании реализуют индивидуальный подход к клиенту, учитывая потребности каждого. Они способны идеально повторить любой шов и реализовать самые сложные идеи.</li>\r\n	<li>Каждый проект мебельной мастерской - это авторская работа квалифицированных мастеров с огромным опытом. “Крафтман” превращает старые вещи в настоящее произведение искусства.</li>\r\n	<li>Мастерская обладает всеми техническими возможностями для качественной работы.</li>\r\n	<li>Гарантия три года.</li>\r\n</ul>\r\n<p style=\"text-indent: 25px;\">Оставляйте заявки у наших менеджеров, чтобы подарить Вашей мебели новую жизнь!</p>\r\n\r\n[/vc_column_text][/vc_column][/vc_row][vc_row disable_element=\"yes\"][vc_column][vc_column_text]\r\n<div style=\"width: 560px; margin: auto;\"><iframe src=\"https://www.youtube.com/embed/2Roc8C_X_NY?rel=0\" width=\"560\" height=\"315\" frameborder=\"0\" allowfullscreen=\"allowfullscreen\"></iframe></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Описание работ по перетяжке и реставрации стульев для столовой\" font_container=\"tag:h1|text_align:center\"][vc_column_text]\r\n<p style=\"text-align: center;\">Стандартный набор услуг, характерный как для перетяжки кухонных стульев, так и для других их видов, состоит из частичной реставрации предметов: удаление с поверхности грязи и царапин. Также производится замена ткани, наполнителя и отделка тесьмой или гвоздиком. Предварительно к вам приезжает представитель компании и показывает образцы материалов, подробно консультируя о необходимых работах.</p>\r\n\r\n[/vc_column_text][us_single_image image=\"3783\" size=\"full\" align=\"center\"][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Преимущества компании Крафтман\" font_container=\"tag:h1|text_align:center\"][/vc_column][/vc_row][vc_row][vc_column width=\"1/4\"][us_single_image image=\"3627\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Собственный магазин обивочных материалов</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3788\" size=\"thumbnail\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Высокотехнологичное оборудование</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3630\" size=\"medium\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Гарантия на работы 3 года</strong></h4>\r\n[/vc_column_text][/vc_column][vc_column width=\"1/4\"][us_single_image image=\"3809\" align=\"center\"][vc_column_text]\r\n<h4 style=\"text-align: center;\"><strong>Собственная служба доставки</strong></h4>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row width=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3689|url^https://kraftman.ru/wp-content/uploads/2018/08/avtobus.png|caption^null|alt^null|title^автобус|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" parallax_sense=\"0\" bg_override=\"full\" disable_on_mobile_img_parallax=\"disable_on_mobile_img_parallax_value\" css=\".vc_custom_1533942966165{padding-top: 100px !important;padding-bottom: 100px !important;}\"][vc_column][vc_raw_html]JTNDZGl2JTIwY2xhc3MlM0QlMjJwbGFudCUyMiUzRSUzQyUyRmRpdiUzRQ==[/vc_raw_html][/vc_column][/vc_row]', 'Перетяжка дивана кожей', '', 'inherit', 'closed', 'closed', '', '2303-revision-v1', '', '', '2018-08-13 01:09:30', '2018-08-12 22:09:30', '', 2303, 'https://kraftman.ru/2303-revision-v1/', 0, 'revision', '', 0),
