(3885, 1, '2018-08-13 13:21:43', '2018-08-13 10:21:43', '[vc_row height=\"full\" bg_type=\"image\" parallax_style=\"vcpb-vz-jquery\" bg_image_new=\"id^3549|url^https://kraftman.ru/wp-content/uploads/2018/08/WhatsApp-Image-2018-08-01-at-15.18.17.jpeg|caption^null|alt^null|title^WhatsApp Image 2018-08-01 at 15.18.17|description^null\" bg_image_repeat=\"no-repeat\" bg_img_attach=\"fixed\" bg_override=\"full\" disable_on_mobile_img_parallax=\"disable_on_mobile_img_parallax_value\"][vc_column][vc_raw_html css=\".vc_custom_1533654358202{padding-top: 90vh !important;}\"][/vc_raw_html][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Широкий ассортимент тканей и кожи\" font_container=\"tag:h1|font_size:62|text_align:center\" google_fonts=\"font_family:Roboto%3A100%2C100italic%2C300%2C300italic%2Cregular%2Citalic%2C500%2C500italic%2C700%2C700italic%2C900%2C900italic|font_style:400%20regular%3A400%3Anormal\"][vc_column_text el_class=\"begtxt\"]\r\n<p style=\"text-align: center;\">Любые обивочные материалы по Вашему индивидуальному запросу. В шоу - руме Крафтман, на Китай-городе, Вы сможете подобрать именно ту обивку, которую ищите!\r\nПридумайте свой рисунок, и мы поможем подобрать именно такой.</p>\r\n[/vc_column_text][vc_custom_heading text=\"Выезд дизайнера с каталогами - бесплатно!\" font_container=\"tag:h1|text_align:center\" google_fonts=\"font_family:Roboto%3A100%2C100italic%2C300%2C300italic%2Cregular%2Citalic%2C500%2C500italic%2C700%2C700italic%2C900%2C900italic|font_style:400%20regular%3A400%3Anormal\"][vc_column_text]\r\n<div class=\"cross2\"><img src=\"https://kraftman.ru/wp-content/uploads/2018/08/2_2.jpg\" alt=\"Пример перетяжки кресла до\" /><img src=\"https://kraftman.ru/wp-content/uploads/2018/08/2_1_2.jpg\" alt=\"Пример перетяжки кресла после\" /></div>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row][vc_column][vc_custom_heading text=\"Основные свойства материалов\" font_container=\"tag:h3|text_align:center\" google_fonts=\"font_family:Robo